    if party then F.status="Close the existing party to apply the changed queue settings" return end
    if P.UserId~=job.owner then F.status="Waiting for the leader to apply Harvard's queue settings" return end
    job.destination=destination write(root.."/job.json",job)
   end
   return requeue(job)
  end
  local step=F.step
  F.step=function()
   if not B.alive or not B.ready or B.safetyPaused() then return end
   return step()
  end
  -- Harvard owns ordinary gearing; Fleet can still equip the exact transferred item.
  local autoStep=B.A.AutoEquip.step
  B.A.AutoEquip.step=function() if B.alive then B.A.AutoEquip.status="Managed by Harvard Gear, Spells & Stats" return end return autoStep() end
  B.restore=function()
   F.snapshot=snapshot F.newJob=newJob F.step=step F.workRequeue=requeue F.destination=destination
   B.A.AutoEquip.step=autoStep
  end
  B.ready=true B.register() B.lastPoll=-math.huge
 end
 function B.adopt(app)
  if not app or not app.Alive or B.App==app then return false end
  if B.restore then B.restore() end
  B.ready=false
  B.oldRerun=app.Settings and app.Settings.RerunOnTeleport
  if app.Settings then app.Settings.RerunOnTeleport=false end
  B.attach(app)
  B.status="Inventory connection restored; continuing the transfer queue"
  B.F.publish(true)
  return true
 end
 function B.start(loader)
  env.InvPlusHarvardBooting=true
  local ok,err=xpcall(function()
   local app=env.InvPlus
   if not app or not app.Alive then app=loader() end
   B.oldRerun=app.Settings and app.Settings.RerunOnTeleport
   if app.Settings then app.Settings.RerunOnTeleport=false end
   B.attach(app)
   if createLobbyUpgrader then createLobbyUpgrader(context,B) end
  end,debug.traceback)
  env.InvPlusHarvardBooting=nil
  if not ok then env.InvPlusHarvardBooting=true B.status="Transfers could not start: "..tostring(err) B.blockQueue=true warn("[Harvard + Inv++] "..B.status) return false end
  if not options.NoWorker then
   task.spawn(function()
    while B.alive and not (context.RT and context.RT.destroyed) do
     local good,message=pcall(function()
      if env.InvPlus and env.InvPlus.Alive and env.InvPlus~=B.App then B.adopt(env.InvPlus) end
      B.register() B.queueSettings()
      local interval=(B.finished() or B.F.isLobby(game.PlaceId)) and 2 or 8
      if clock()-(B.refreshedAt or -math.huge)>=interval then B.refresh() B.refreshedAt=clock() end
      B.poll(true)
      if B.label and B.label.Parent then B.label.Text=B.status end
      if B.control and B.control.render then B.control.render() end
     end)
     if not good then B.blockQueue=true B.status="Transfer check failed: "..tostring(message):sub(1,120) end
     task.wait(1)
    end
   end)
   table.insert(B.connections,P.OnTeleport:Connect(function(state)
    if state~=Enum.TeleportState.Started or not B.alive then return end
    local queue=queue_on_teleport or (syn and syn.queue_on_teleport)
    if type(queue)~="function" then warn("[Harvard + Inv++] Auto-execute this file after teleport; queue_on_teleport is unavailable") return end
    pcall(queue,string.format([[getgenv().InvPlusSession={userId=%d,startedAt=%d} repeat task.wait() until game:IsLoaded() task.wait(2) local c=getgenv().InvPlusHarvardContext if not (c and c.RT and not c.RT.destroyed) then loadstring(readfile("Harvard-InvPlus.lua"))() end]],P.UserId,B.App.SessionStartedAt or now()))
   end))
  end
  return true
 end
 function B.mount(parent,ui,track)
  local section=ui.section(parent,"Inv++ Account Transfers",2.5,"Reserves useful drops for your other accounts. Finishes the run, trades in the lobby, then queues everyone together using Harvard's party settings.").content
  B.control=ui.toggle(section,"Automatic transfers",function() return B.F and B.F.config.automatic==true end,function(enabled)
   if B.ready then B.F.setAutomatic(enabled) B.lastPoll=-math.huge end
  end,1,"Online registered accounts must run Harvard. Offline accounts are skipped for new queues; an unfinished item transfer waits for its participants. Auto sell protects useful gear.")
  if track then track(B.control) end
  B.label=ui.caption(section,B.status,2)
 end
 function B.destroy()
  if not B.alive then return end B.alive=false
  env.InvPlusHarvardBooting=nil
  for _,c in ipairs(B.connections) do c:Disconnect() end
  if B.restore then B.restore() end
  if B.App and B.App.Settings then B.App.Settings.RerunOnTeleport=B.oldRerun end
 end
 return B
end
]==], "Harvard transfer integration"))()(context)
end
local function loadBundledInvPlus()
 return assert(loadstring([=[
