Modules.history=function()
-- Passive local history. Existing inventory is first-seen, never backdated.
return function(C)
 local P=game:GetService("Players").LocalPlayer
 local Http=game:GetService("HttpService")
 local H={alive=true,store={version=1,items={}},pending={},rewards={},recent={},known={},baselineReady=false,connections={},dirty=false}
 H.path="Inv++/item_history_"..tostring(P.UserId)..".json"
 -- Import the existing history once; the standalone copy lives under Inv++.
 local legacy="Laplace/item_history_"..tostring(P.UserId)..".json"
 if not isfile(H.path) and isfile(legacy) then
  local ok,data=pcall(readfile,legacy)
  if ok then local written,why=pcall(writefile,H.path,data) if not written then warn("[Inv++] History import: "..tostring(why)) end end
 end
 if isfile(H.path) then
  local ok,data=pcall(function() return Http:JSONDecode(readfile(H.path)) end)
  if ok and type(data)=="table" and data.version==1 and type(data.items)=="table" then H.store=data
  else H.readError="Could not read saved item history" warn("[InvPlus] "..H.readError) end
 end
 function H.uid(record)
  local value=record and record.item and record.item.UniqueItemID
  return type(value)=="string" and value~="" and value or nil
 end
 function H.save()
  if not H.dirty or H.readError then return end
  local ok,err=pcall(function() writefile(H.path,Http:JSONEncode(H.store)) end)
  if ok then H.dirty=false else H.saveError=tostring(err) end
 end
 function H.changed()
  H.dirty=true
  if H.scheduled then return end H.scheduled=true
  task.delay(.75,function() H.scheduled=false if H.alive then H.save() end end)
 end
 function H.context()
  local dungeon=workspace:FindFirstChild("dungeonName")
  local difficulty=workspace:FindFirstChild("difficulty") or game:GetService("ReplicatedStorage"):FindFirstChild("difficulty")
  local name=dungeon and dungeon:IsA("ValueBase") and tostring(dungeon.Value) or nil
  local mode=difficulty and difficulty:IsA("ValueBase") and tostring(difficulty.Value) or nil
  return name and name~="" and (name..(mode and mode~="" and " · "..mode or "")) or nil
 end
 local function normalized(value) return tostring(value or ""):lower():match("^%s*(.-)%s*$") end
 local function imageID(value) return tostring(value or ""):match("%d+") end
 function H.matches(reward,record)
  local item=record.item
  if normalized(reward.name)~=normalized(item.name) then return false end
  if reward.rarity and normalized(reward.rarity)~=normalized(item.rarity) then return false end
  if reward.image and imageID(item.imageId) and reward.image~=imageID(item.imageId) then return false end
  for _,field in ipairs({"physicalDamage","physicalPower","spellPower","health","maxUpgrades"}) do
   if reward[field]~=nil and tonumber(reward[field])~=tonumber(item[field]) then return false end
  end
  return true
 end
 function H.confirm(uid,reward)
  local entry=H.store.items[uid]
  if entry and not entry.droppedAt then
   entry.droppedAt=reward.at entry.source=reward.source entry.acquisition=reward.acquisition or "drop"
   entry.confirmation="reward-inventory-match" H.changed()
   local auto=C.Godpot.AutoEquip
   if auto then auto.onDrop(uid,entry) end
   local webhook=C.Godpot.Webhook
   if webhook then
    local record=H.recent[uid] and H.recent[uid].record
    local ok=pcall(webhook.onDrop,uid,entry,record)
    if not ok then webhook.status="Could not queue the drop notification." webhook.lastError=webhook.status end
   end
  end
 end
 function H.reconcile(now)
  now=now or os.time()
  for _,reward in ipairs(H.rewards) do
   if not reward.done and now-reward.at<=90 then
    local candidates={}
    for uid,record in pairs(H.recent) do
     local entry=H.store.items[uid]
     if entry and not entry.droppedAt and math.abs(record.at-reward.at)<=90 and H.matches(reward,record.record) then table.insert(candidates,uid) end
    end
    local enough=#candidates==1
    if #candidates>1 then
     local count=0
     for _,other in ipairs(H.rewards) do
      if not other.done and math.abs(other.at-reward.at)<=90 then
       local all=true for _,uid in ipairs(candidates) do if not H.matches(other,H.recent[uid].record) then all=false break end end
       if all then count+=1 end
      end
     end
     enough=count>=#candidates
    end
    if enough then table.sort(candidates) H.confirm(candidates[1],reward) reward.done=true end
   end
  end
  for uid,record in pairs(H.recent) do if now-record.at>90 then H.recent[uid]=nil end end
  for i=#H.rewards,1,-1 do if H.rewards[i].done or now-H.rewards[i].at>90 then table.remove(H.rewards,i) end end
 end
 function H.ingest(index)
  local now=os.time()
  for _,record in pairs(index) do
   local uid=H.uid(record)
   if uid then
    local entry=H.store.items[uid]
    local fresh=not entry
    if fresh then entry={firstSeen=now,name=record.item.name,kind=record.kind} H.store.items[uid]=entry H.changed() end
    if H.baselineReady and not H.known[uid] and fresh then H.recent[uid]={at=now,record=record} end
    H.known[uid]=true
    local pending=H.pending[uid]
    if pending then H.confirm(uid,pending) H.pending[uid]=nil end
   end
  end
  if next(index)~=nil then H.baselineReady=true end H.reconcile(now)
 end
 -- Current reward payload: { items = { {itemName, rarity, imageId, ...}, ... } }.
 -- Keep descriptors until a fresh inventory UID confirms ownership, regardless of event order.
 function H.reward(payload,at,source)
  at=at or os.time()
  local envelope=type(payload)=="table" and (payload.items and payload or type(payload[1])=="table" and payload[1].items and payload[1])
  if envelope then
   local daily=envelope.isDailyReward==true
   for _,item in pairs(envelope.items) do
    if type(item)=="table" then
     local uid=type(item.UniqueItemID)=="string" and item.UniqueItemID or nil
     local reward={at=at,source=daily and "Daily Reward" or source,acquisition=daily and "reward" or "drop"}
     if uid then H.pending[uid]=reward
     elseif type(item.itemName or item.name)=="string" then
      reward.name=item.itemName or item.name reward.rarity=item.rarity reward.image=imageID(item.imageId)
      for _,field in ipairs({"physicalDamage","physicalPower","spellPower","health","maxUpgrades"}) do reward[field]=item[field] end
      table.insert(H.rewards,reward)
     end
    end
   end
  else
   -- Retain support for reward variants that do include unique IDs.
   local visited,budget={},500
   local function scan(value,depth)
    budget-=1 if budget<0 or depth>6 then return end
    if type(value)=="table" and not visited[value] then
     visited[value]=true
     if type(value.UniqueItemID)=="string" then H.pending[value.UniqueItemID]={at=at,source=source} end
     for _,child in pairs(value) do scan(child,depth+1) end
    elseif type(value)=="string" then
     for _,record in pairs(C.Godpot.index) do if H.uid(record)==value then H.pending[value]={at=at,source=source} break end end
    end
   end
   scan(payload,0)
  end
  H.ingest(C.Godpot.index)
 end
 function H.age(timestamp,now)
  local seconds=math.max(0,(now or os.time())-timestamp)
  if seconds<60 then return "Just now" end
  local n,unit
  if seconds<3600 then n=math.floor(seconds/60) unit="minute"
  elseif seconds<86400 then n=math.floor(seconds/3600) unit="hour"
  else n=math.floor(seconds/86400) unit="day" end
  return tostring(n).." "..unit..(n==1 and "" or "s").." ago"
 end
 function H.build(inv,source)
  if H.card and H.card.Parent==inv then return end
  if H.card then H.card:Destroy() end
  local card=source:Clone() card:ClearAllChildren()
  card.Name="InvPlusItemHistory" card.AnchorPoint=Vector2.zero card.Rotation=0
  card.ImageColor3=Color3.new(0,0,0) card.ZIndex=16 card.Visible=false card.Parent=inv H.card=card
  local border=source:FindFirstChild("border")
  if border then
   local edge=border:Clone() edge.Name="border" edge.ImageColor3=Color3.fromRGB(86,86,86)
   edge.ZIndex=15 edge.Parent=card
  end
  local separator=source:FindFirstChild("separater")
  if separator then
   local line=separator:Clone() line.Position=UDim2.fromOffset(0,33) line.Size=UDim2.new(1,0,0,1)
   line.BackgroundColor3=Color3.fromRGB(160,160,160) line.BackgroundTransparency=.3 line.ZIndex=17 line.Parent=card
  end
  H.lines={}
  for index,name in ipairs({"Title","Date","Time","Source","Age"}) do
   local template=index==1 and source:FindFirstChild("name") or source:FindFirstChild("damageTitle") or source:FindFirstChild("levelReqTitle") or source:FindFirstChild("levelReq")
   local label=template:Clone() label:ClearAllChildren() label.Name=name label.BackgroundTransparency=1
   label.TextColor3=index==1 and Color3.new(1,1,1) or Color3.fromRGB(213,213,213)
   label.TextStrokeTransparency=1 label.TextYAlignment=Enum.TextYAlignment.Center
   label.AnchorPoint=index==1 and Vector2.new(.5,0) or Vector2.zero
   label.TextXAlignment=index==1 and Enum.TextXAlignment.Center or Enum.TextXAlignment.Left
   label.Position=index==1 and UDim2.fromScale(.5,0) or UDim2.new(.04,0,0,39+(index-2)*27)
   label.Size=index==1 and UDim2.new(.9,0,0,31) or UDim2.new(.92,0,0,25)
   label.Visible=true label.TextTransparency=0 label.TextScaled=true label.ZIndex=17 label.Parent=card
   local limit=Instance.new("UITextSizeConstraint") limit.MinTextSize=10 limit.MaxTextSize=index==1 and 22 or 20 limit.Parent=label H.lines[name]=label
  end
  H.lines.Title.Text="Item History"
 end
 function H.hide() if H.card then H.card.Visible=false end end
 function H.place(pos,size,cardSize,viewport)
  local gap=8 local x=math.clamp(pos.X,4,math.max(4,viewport.X-cardSize.X-4))
  local y=pos.Y+size.Y+gap local above=false
  if y+cardSize.Y>viewport.Y-4 then y=pos.Y-cardSize.Y-gap above=true end
  y=math.clamp(y,4,math.max(4,viewport.Y-cardSize.Y-4))
  return Vector2.new(x,y),above
 end
 function H.show(frame,record)
  local inv=frame:FindFirstAncestorOfClass("ScreenGui") if not inv then H.hide() return end
  H.build(inv,frame)
  local entry=H.store.items[H.uid(record) or ""]
  local timestamp=entry and (entry.droppedAt or entry.firstSeen)
  local date,time="Unknown","Unknown"
  if type(timestamp)=="number" then
   local instant=DateTime.fromUnixTimestamp(timestamp)
   date=instant:FormatLocalTime("MMM D, YYYY","en-us") time=instant:FormatLocalTime("h:mm A","en-us")
  end
  H.lines.Date.Text=(entry and entry.droppedAt and (entry.acquisition=="reward" and "Received: " or "Dropped: ") or "First seen: ")..date
  H.lines.Time.Text="Time: "..time
  H.lines.Source.Text="From: "..(entry and entry.source or "Unconfirmed")
  H.lines.Age.Text="Age: "..(timestamp and H.age(timestamp) or "Unknown")
  local width=frame.AbsoluteSize.X
  local cardSize=Vector2.new(width,153)
  local camera=workspace.CurrentCamera local viewport=camera and camera.ViewportSize or Vector2.new(1920,1080)
  if not inv.IgnoreGuiInset then viewport-=game:GetService("GuiService"):GetGuiInset() end
  local position,above=H.place(frame.AbsolutePosition,frame.AbsoluteSize,cardSize,viewport)
  H.card.Size=UDim2.fromOffset(cardSize.X,cardSize.Y) H.card.Position=UDim2.fromOffset(position.X,position.Y) H.card.Visible=true H.above=above
  return H.card
 end
 function H.hovered()
  local inv=P.PlayerGui:FindFirstChild("inventory") local main=inv and inv:FindFirstChild("mainBackground") local inner=main and main:FindFirstChild("innerBackground")
  if not inner then return nil end
  local mouse=game:GetService("UserInputService"):GetMouseLocation()
  if not inv.IgnoreGuiInset then mouse-=game:GetService("GuiService"):GetGuiInset() end
  local right=inner:FindFirstChild("rightSideFrame") local bag=right and right:FindFirstChild("ScrollingFrame") local left=inner:FindFirstChild("leftSideFrame")
  local function hit(object)
   if not object.Visible then return false end local p,s=object.AbsolutePosition,object.AbsoluteSize
   return mouse.X>=p.X and mouse.X<=p.X+s.X and mouse.Y>=p.Y and mouse.Y<=p.Y+s.Y
  end
  for _,container in ipairs({bag or false,left or false}) do
   if container and hit(container) then for _,card in ipairs(container:GetChildren()) do
    if card:IsA("GuiObject") and hit(card) then
     local t=card:FindFirstChild("itemType") local id=t and t:FindFirstChild("uniqueItemNum")
     local record=id and C.Godpot.index[t.Value..":"..tostring(id.Value)] if record then return record end
    end
   end end
  end
 end
 function H.destroy()
  H.alive=false H.save()
  for _,connection in ipairs(H.connections) do connection:Disconnect() end
  if H.card then H.card:Destroy() end
 end
 local remotes=game:GetService("ReplicatedStorage"):FindFirstChild("remotes")
 local inventoryUpdate=remotes and remotes:FindFirstChild("updateLocalInventoryTable")
 if inventoryUpdate and inventoryUpdate:IsA("RemoteEvent") then table.insert(H.connections,inventoryUpdate.OnClientEvent:Connect(function(inv)
  if type(inv)=="table" and (type(inv.weapons)=="table" or type(inv.helmets)=="table" or type(inv.abilities)=="table") then
   C.Inventory.cache=inv C.Godpot.ingest(inv)
  end
 end)) end
 local reward=remotes and remotes:FindFirstChild("cloneRewardGui")
 if reward and reward:IsA("RemoteEvent") then table.insert(H.connections,reward.OnClientEvent:Connect(function(...)
  H.reward({...},os.time(),H.context())
  task.delay(.3,function() if H.alive then C.Inventory.fetch() end end)
 end)) end
 return H
end

end

Modules.sorting=function()
-- Native inventory ordering only; never equips, upgrades or sells items.
return function(C)
 local A=C.Godpot
 local S={mode=nil,query="",predicates={},filters={rarity="all"},original={},visibility={},buttons={},filterButtons={},connections={}}
 local P=game:GetService("Players").LocalPlayer
 local names={"Mage","Warrior","Guardian","Highest Pot"}
 local colors={Mage=Color3.fromRGB(105,170,255),Warrior=Color3.fromRGB(242,105,105),Guardian=Color3.fromRGB(135,232,121)}
 function S.class(record)
  local item,kind=record.item,record.kind
  local name=tostring(item.name):lower()
  local entry=A.entry(item.name,kind)
  local class=entry and tostring(entry.c):lower() or ""
  if name:find("guardian",1,true) or class:find("guardian",1,true) then return "Guardian" end
  if name:find("mage",1,true) or class:find("mage",1,true) then return "Mage" end
  if name:find("warrior",1,true) or class:find("war",1,true) then return "Warrior" end
  if kind=="ability" then
   local description=tostring(item.description or ""):lower()
   if description:find("spell",1,true) then return "Mage" end
   if description:find("physical",1,true) then return "Warrior" end
   if description:find("health",1,true) or description:find("heal",1,true) then return "Guardian" end
  end
  local physical=tonumber(item.physicalDamage or item.physicalPower) or 0
  local spell=tonumber(item.spellPower) or 0
  if physical~=spell then return spell>physical and "Mage" or "Warrior" end
 end
 function S.restore()
  for card,order in pairs(S.original) do if card.Parent then card.LayoutOrder=order end end
  table.clear(S.original)
 end
 function S.restoreVisibility()
  for card,visible in pairs(S.visibility) do if card.Parent then card.Visible=visible end end
  table.clear(S.visibility)
 end
 local rarities={common=true,uncommon=true,rare=true,epic=true,legendary=true,mythic=true,divine=true}
 local classes={mage="Mage",warrior="Warrior",guardian="Guardian",war="Warrior",tank="Guardian"}
 local types={weapon="weapon",weapons="weapon",armor="armor",armour="armor",helmet="helmet",helmets="helmet",chest="chest",chests="chest",ability="ability",abilities="ability"}
 local function normalized(value)
  local text=tostring(value or ""):lower():match("^%s*(.-)%s*$")
  return text=="mythical" and "mythic" or text
 end
 function S.equipped(record)
  local value=record.item.equipped
  if type(value)=="table" then for _,equipped in pairs(value) do if equipped==true then return true end end return false end
  return value==true
 end
 function S.upgrade(record)
  if not record or record.kind=="ability" then return false end
  local result=A.compare(record,A.equipped(record.kind))
  return result~=nil and result.delta~=nil and result.delta>0
 end
 local function typeMatches(kind,wanted) return kind==wanted or wanted=="armor" and (kind=="helmet" or kind=="chest") end
 function S.history(record)
  local uid=record.item.UniqueItemID
  return A.History and uid and A.History.store.items[uid] or nil
 end
 function S.newDrop(record)
  local history=S.history(record)
  return history and history.droppedAt~=nil and history.acquisition~="reward" and os.time()-history.droppedAt<=1800 or false
 end
 function S.tokenize(query)
  local tokens,buffer={},{} local quoted=false local literal=false
  local function flush()
   if #buffer>0 then table.insert(tokens,{text=table.concat(buffer),literal=literal}) buffer={} literal=false end
  end
  for i=1,#query do
   local ch=query:sub(i,i)
   if ch=='"' then
    if #buffer==0 or #buffer==1 and buffer[1]=="-" then literal=true end
    quoted=not quoted
   elseif ch:match("%s") and not quoted then flush() else table.insert(buffer,ch) end
  end
  if quoted then return nil,"Close quote" end
  flush() return tokens
 end
 function S.compile(query)
  local tokens,err=S.tokenize(query) if not tokens then return nil,err end
  local predicates={}
  for _,token in ipairs(tokens) do
   local word=normalized(token.text) local negate=word:sub(1,1)=="-"
   if negate then word=word:sub(2) end
   local predicate
   local field,op,value=word:match("^([%a]+)([<>!=:]+)(.*)$")
   if token.literal then field=nil end
   if field=="name" or field=="class" or field=="type" or field=="rarity" or field=="tag" then
    if op~=":" or value=="" then return nil,"Use "..field..":value" end
    local wanted=value
    if field=="name" then predicate=function(r) return normalized(r.item.name):find(wanted,1,true)~=nil end
    elseif field=="tag" then
     if not ({keep=true,trade=true,upgrade=true,none=true})[wanted] then return nil,"Unknown tag" end
     predicate=function(r) local tag=A.Review and A.Review.getTag(r.item.UniqueItemID) return (tag and tag:lower() or "none")==wanted end
    elseif field=="class" then
     if not classes[wanted] then return nil,"Unknown class" end
     predicate=function(r) return S.class(r)==classes[wanted] end
    elseif field=="type" then
     if not types[wanted] then return nil,"Unknown type" end
     predicate=function(r) return typeMatches(r.kind,types[wanted]) end
    else
     wanted=normalized(wanted) if not rarities[wanted] then return nil,"Unknown rarity" end
     predicate=function(r) return normalized(r.item.rarity)==wanted end
    end
   elseif field then
    local valid={pot=true,godpot=true,level=true,lvl=true,upgrades=true,remaining=true,max=true,age=true}
    if not valid[field] then return nil,"Unknown: "..field end
    if op==":" or op=="==" then op="=" end
    if not ({[">"]=true,[">="]=true,["<"]=true,["<="]=true,["="]=true,["!="]=true})[op] then return nil,"Check operator" end
    local number,suffix=value:match("^(%d*%.?%d+)([%a%%]*)$")
    number=tonumber(number)
    if not number then return nil,"Check "..field.." value" end
    if field=="age" then
     local units={s=1,m=60,h=3600,d=86400,[""]=1}
     if not units[suffix] then return nil,"Age: use m/h/d" end number*=units[suffix]
    elseif field=="max" then
     local units={k=1e3,m=1e6,b=1e9,t=1e12,[""]=1}
     if not units[suffix] then return nil,"Max: use K/M/B" end number*=units[suffix]
    elseif suffix~="" and not ((field=="pot" or field=="godpot") and suffix=="%") then return nil,"Check "..field.." value" end
    predicate=function(r)
     local actual
     if field=="pot" or field=="godpot" then actual=A.compute(r.item,r.kind)
     elseif field=="level" or field=="lvl" then actual=tonumber(r.item.levelReq)
     elseif field=="upgrades" then actual=tonumber(r.item.currentUpgrade)
     elseif field=="remaining" then local maximum=tonumber(r.item.maxUpgrades) if maximum then actual=math.max(0,maximum-(tonumber(r.item.currentUpgrade) or 0)) end
     elseif field=="max" then local result=A.compare(r,nil) actual=result and result.value
     else local history=S.history(r) local stamp=history and (history.droppedAt or history.firstSeen) if stamp then actual=math.max(0,os.time()-stamp) end end
     if actual==nil then return false end
     if op==">" then return actual>number elseif op==">=" then return actual>=number elseif op=="<" then return actual<number elseif op=="<=" then return actual<=number elseif op=="!=" then return actual~=number else return actual==number end
    end
   elseif not token.literal and classes[word] then predicate=function(r) return S.class(r)==classes[word] end
   elseif not token.literal and types[word] then predicate=function(r) return typeMatches(r.kind,types[word]) end
   elseif not token.literal and rarities[word] then predicate=function(r) return normalized(r.item.rarity)==word end
   elseif not token.literal and (word=="upgrade" or word=="upgrades" or word=="better") then predicate=S.upgrade
   elseif not token.literal and word=="equipped" then predicate=S.equipped
   elseif not token.literal and word=="unequipped" then predicate=function(r) return not S.equipped(r) end
   elseif not token.literal and word=="new" then predicate=S.newDrop
   elseif not token.literal and word=="best" then predicate=function(r) return A.Extras and A.Extras.isBest(r) or false end
   elseif not token.literal and word=="duplicates" then predicate=function(r) return A.Extras and (A.Extras.groups[A.Extras.groupKey(r)] or 0)>1 or false end
   elseif not token.literal and word=="session" then predicate=function(r) local h=S.history(r) return h and h.droppedAt and h.acquisition~="reward" and h.droppedAt>=A.SessionStartedAt or false end
   elseif word~="" then predicate=function(r) return normalized(r.item.name):find(word,1,true)~=nil end
   else return nil,"Missing term" end
   local test=predicate
   if negate then predicate=function(r) return not test(r) end end
   table.insert(predicates,predicate)
  end
  return predicates
 end
 function S.setQuery(query)
  S.query=tostring(query or ""):match("^%s*(.-)%s*$")
  local predicates,err=S.compile(S.query)
  S.error=err if predicates then S.predicates=predicates end
  S.apply()
  local _,inner=S.rows() if inner then inner.rightSideFrame.ScrollingFrame.CanvasPosition=Vector2.zero end
 end
 function S.matches(record)
  if not record then return false end
  local filters=S.filters
  if filters.type and not typeMatches(record.kind,filters.type) then return false end
  if filters.upgrade and not S.upgrade(record) then return false end
  if filters.new and not S.newDrop(record) then return false end
  if filters.rarity~="all" and normalized(record.item.rarity)~=filters.rarity then return false end
  for _,predicate in ipairs(S.predicates) do if not predicate(record) then return false end end
  return true
 end
 function S.filter(rows)
  local active=#S.predicates>0 or S.filters.type or S.filters.upgrade or S.filters.new or S.filters.rarity~="all"
  if not active then S.restoreVisibility() end
  local shown=0
  for _,row in ipairs(rows) do
   local card=row.card
   if active then
    if S.visibility[card]==nil then S.visibility[card]=card.Visible end
    card.Visible=S.visibility[card] and S.matches(row.record)
   end
   if card.Visible then shown+=1 end
  end
  S.matchCount=shown S.totalCount=#rows
  if S.status then S.status.Text=S.error or tostring(shown).." / "..tostring(#rows) S.status.TextColor3=S.error and Color3.fromRGB(242,105,105) or Color3.fromRGB(200,200,200) end
  if S.search then S.search.TextColor3=S.error and Color3.fromRGB(242,105,105) or Color3.fromRGB(254,254,254) end
 end
 function S.refreshButtons()
  local selected=Color3.fromRGB(255,241,132)
  for name,button in pairs(S.buttons) do
   button.text.TextColor3=colors[name] or (name==S.mode and selected or button.color)
   button.face.ImageColor3=name==S.mode and Color3.fromRGB(86,86,86) or button.faceColor
  end
  for id,button in pairs(S.filterButtons) do
   local active=id=="rarity" and S.filters.rarity~="all" or id=="upgrade" and S.filters.upgrade or id=="new" and S.filters.new or S.filters.type==id
   button.text.TextColor3=active and selected or button.color button.face.ImageColor3=active and Color3.fromRGB(86,86,86) or button.faceColor
   if id=="rarity" then local value=S.filters.rarity button.text.Text="Rarity: "..value:sub(1,1):upper()..value:sub(2) end
  end
 end
 function S.setFilter(id)
  if id=="rarity" then
   local present={} for _,r in pairs(A.index) do present[normalized(r.item.rarity)]=true end
   local options={"all"} for _,rarity in ipairs({"common","uncommon","rare","epic","legendary","mythic","divine"}) do if present[rarity] then table.insert(options,rarity) end end
   local current=table.find(options,S.filters.rarity) or 1 S.filters.rarity=options[current%#options+1]
  elseif id=="upgrade" or id=="new" then S.filters[id]=not S.filters[id]
  else S.filters.type=S.filters.type~=id and id or nil end
  S.refreshButtons() S.apply()
  local _,inner=S.rows() if inner then inner.rightSideFrame.ScrollingFrame.CanvasPosition=Vector2.zero end
 end
 function S.rows()
  local inv=P.PlayerGui:FindFirstChild("inventory")
  local main=inv and inv:FindFirstChild("mainBackground")
  local inner=main and main:FindFirstChild("innerBackground")
  local right=inner and inner:FindFirstChild("rightSideFrame")
  local bag=right and right:FindFirstChild("ScrollingFrame")
  local rows={}
  if bag then for _,card in ipairs(bag:GetChildren()) do
   local t=card:IsA("GuiObject") and card:FindFirstChild("itemType")
   local id=t and t:FindFirstChild("uniqueItemNum")
   if id then
    if S.original[card]==nil then S.original[card]=card.LayoutOrder end
    local record=A.index[t.Value..":"..tostring(id.Value)]
    local score,matching=-math.huge,false
    if record then
     if S.mode=="Highest Pot" then score=A.compute(record.item,record.kind) or -math.huge matching=score>-math.huge
     elseif S.mode then
      matching=S.class(record)==S.mode
      local field=S.mode=="Guardian" and "health" or S.mode=="Mage" and "spellPower" or (record.kind=="weapon" and "physicalDamage" or "physicalPower")
      score=A.potential(record.item[field],math.max(0,(tonumber(record.item.maxUpgrades) or 0)-(tonumber(record.item.currentUpgrade) or 0))) or -math.huge
     end
    end
    table.insert(rows,{card=card,record=record,matching=matching,score=score,original=S.original[card]})
   end
  end end
  return rows,inner,right
 end
 function S.apply()
  local rows=S.rows()
  S.filter(rows)
  if A.Extras then A.Extras.filter(rows) end
  if not S.mode then return end
  table.sort(rows,function(a,b)
   if a.matching~=b.matching then return a.matching end
   if a.matching and a.score~=b.score then return a.score>b.score end
   if a.original~=b.original then return a.original<b.original end
   return a.card.Name<b.card.Name
  end)
  for rank,row in ipairs(rows) do row.card.LayoutOrder=rank end
 end
 function S.select(mode)
  S.restore()
  S.mode=S.mode~=mode and mode or nil
  S.apply()
  S.refreshButtons()
  local _,inner=S.rows()
  if inner then inner.rightSideFrame.ScrollingFrame.CanvasPosition=Vector2.zero end
 end
 function S.build(inner)
  if S.panel and S.panel.Parent==inner then return end
  if S.panel then S.panel:Destroy() end
  if S.searchBar then S.searchBar:Destroy() end
  for _,connection in ipairs(S.connections) do connection:Disconnect() end table.clear(S.connections) table.clear(S.buttons) table.clear(S.filterButtons)
  local keys=inner:FindFirstChild("keysFrameBorder")
  local source=keys and keys:FindFirstChild("keysFrameInner")
  local main=inner.Parent
  local tab=main:FindFirstChild("gearTab")
  local template=tab and tab:FindFirstChild("ImageLabel") and tab.ImageLabel:FindFirstChild("TextButton")
  if not source or not template then return end
  local panel=Instance.new("Frame") panel.Name="InvPlusInventorySort" panel.BackgroundTransparency=1
  panel.AnchorPoint=keys.AnchorPoint
  panel.Position=UDim2.new(keys.Position.X.Scale,keys.Position.X.Offset,keys.Position.Y.Scale+keys.Size.Y.Scale+.025,keys.Position.Y.Offset+keys.Size.Y.Offset)
  panel.Size=UDim2.new(keys.Size.X.Scale,keys.Size.X.Offset,.36,0) panel.Parent=inner S.panel=panel
  for index,name in ipairs(names) do
   local border=keys:Clone() border:ClearAllChildren() border.Name=name:gsub(" ","")
   border.AnchorPoint=Vector2.zero border.Position=UDim2.fromScale(0,(index-1)*.255) border.Size=UDim2.fromScale(1,.235) border.ZIndex=3 border.Parent=panel
   local face=source:Clone() face:ClearAllChildren() face.Name="Face" face.AnchorPoint=Vector2.new(.5,.5) face.Position=UDim2.fromScale(.5,.5) face.Size=UDim2.fromScale(.95,.88) face.ZIndex=4 face.Parent=border
   local text=template:Clone() text:ClearAllChildren() text.Name="SortButton" text.Rotation=0 text.AnchorPoint=Vector2.new(.5,.5) text.Position=UDim2.fromScale(.5,.5) text.Size=UDim2.fromScale(.9,.82)
   text.Text=name text.TextColor3=colors[name] or text.TextColor3 text.TextScaled=true text.ZIndex=5 text.Active=true text.Parent=face
   S.buttons[name]={text=text,face=face,color=text.TextColor3,faceColor=face.ImageColor3}
   table.insert(S.connections,text.Activated:Connect(function() S.select(name) end))
  end
  for index,definition in ipairs({{"weapon","Weapons"},{"armor","Armor"},{"ability","Abilities"},{"upgrade","Upgrades"},{"new","New Drops"},{"rarity","Rarity: All"}}) do
   local id,title=definition[1],definition[2] local column=(index-1)%2 local row=math.floor((index-1)/2)
   local border=keys:Clone() border:ClearAllChildren() border.Name="Filter_"..id border.AnchorPoint=Vector2.zero
   border.Position=UDim2.fromScale(column*.515,1.035+row*.255) border.Size=UDim2.fromScale(.485,.235) border.ZIndex=3 border.Parent=panel
   local face=source:Clone() face:ClearAllChildren() face.Name="Face" face.AnchorPoint=Vector2.new(.5,.5) face.Position=UDim2.fromScale(.5,.5) face.Size=UDim2.fromScale(.92,.88) face.ZIndex=4 face.Parent=border
   local text=template:Clone() text:ClearAllChildren() text.Name="FilterButton" text.Rotation=0 text.AnchorPoint=Vector2.new(.5,.5) text.Position=UDim2.fromScale(.5,.5) text.Size=UDim2.fromScale(.9,.8)
   text.Text=title text.TextScaled=true text.ZIndex=5 text.Parent=face
   local limit=Instance.new("UITextSizeConstraint") limit.MinTextSize=10 limit.MaxTextSize=20 limit.Parent=text
   S.filterButtons[id]={text=text,face=face,color=text.TextColor3,faceColor=face.ImageColor3}
   table.insert(S.connections,text.Activated:Connect(function() S.setFilter(id) end))
  end
  S.refreshButtons()
  local border=Instance.new("Frame") border.Name="InvPlusInventorySearch" border.BorderSizePixel=0 border.BackgroundColor3=keys.ImageColor3
  border.AnchorPoint=Vector2.new(.5,0) border.Position=UDim2.fromScale(.5,1.018) border.Size=UDim2.fromScale(1,.085) border.ZIndex=3 border.Parent=main S.searchBar=border
  local round=Instance.new("UICorner") round.CornerRadius=UDim.new(.5,0) round.Parent=border
  local face=Instance.new("Frame") face.Name="Face" face.BorderSizePixel=0 face.BackgroundColor3=source.ImageColor3
  face.AnchorPoint=Vector2.new(.5,.5) face.Position=UDim2.fromScale(.5,.5) face.Size=UDim2.new(1,-12,1,-12) face.ZIndex=4 face.Parent=border
  local innerRound=round:Clone() innerRound.Parent=face
  local input=Instance.new("TextBox") input.Name="SearchInput" input.BackgroundTransparency=1 input.BorderSizePixel=0
  input.Position=UDim2.fromScale(.025,.1) input.Size=UDim2.fromScale(.71,.8)
  input.FontFace=template.FontFace input.TextColor3=template.TextColor3 input.TextStrokeColor3=template.TextStrokeColor3 input.TextStrokeTransparency=template.TextStrokeTransparency
  input.PlaceholderText="Search · mage epic pot>90 level:195 · quotes for names" input.PlaceholderColor3=Color3.fromRGB(195,195,195)
  input.TextScaled=true input.ClearTextOnFocus=false input.MultiLine=false input.TextXAlignment=Enum.TextXAlignment.Left input.Text=S.query input.ZIndex=5 input.Parent=face S.search=input
  local limit=Instance.new("UITextSizeConstraint") limit.MinTextSize=10 limit.MaxTextSize=26 limit.Parent=input
  local clear=template:Clone() clear:ClearAllChildren() clear.Name="ClearSearch" clear.Rotation=0 clear.AnchorPoint=Vector2.new(.5,.5)
  clear.Position=UDim2.fromScale(.96,.5) clear.Size=UDim2.fromScale(.04,.72) clear.Text="×" clear.TextScaled=true clear.ZIndex=5 clear.Parent=face
  local status=Instance.new("TextLabel") status.Name="SearchStatus" status.BackgroundTransparency=1 status.Font=Enum.Font.Highway status.TextColor3=Color3.fromRGB(200,200,200)
  status.TextXAlignment=Enum.TextXAlignment.Right status.Position=UDim2.fromScale(.75,.1) status.Size=UDim2.fromScale(.17,.8) status.TextScaled=true status.ZIndex=5 status.Parent=face S.status=status
  local statusLimit=Instance.new("UITextSizeConstraint") statusLimit.MinTextSize=10 statusLimit.MaxTextSize=18 statusLimit.Parent=status
  table.insert(S.connections,input:GetPropertyChangedSignal("Text"):Connect(function() S.setQuery(input.Text) end))
  table.insert(S.connections,clear.Activated:Connect(function() input.Text="" end))
 end
 function S.update()
  local _,inner,right=S.rows()
  if inner then
   S.build(inner)
   local keys=inner:FindFirstChild("keysFrameBorder")
   if S.panel then S.panel.Visible=keys and keys.Visible and right.Visible or false end
   if S.searchBar then S.searchBar.Visible=right.Visible end
   S.apply()
  end
 end
 function S.destroy()
  S.restoreVisibility()
  S.restore()
  for _,connection in ipairs(S.connections) do connection:Disconnect() end
  if S.panel then S.panel:Destroy() end
  if S.searchBar then S.searchBar:Destroy() end
 end
 return S
end

end

Modules.fleet=function()
return function(C)
 local A=C.Godpot local P=C.Player or game.Players.LocalPlayer local RS=game.ReplicatedStorage local Http=game:GetService("HttpService")
 local F={alive=true,status="Tracking inventories",connections={},nonce=Http:GenerateGUID(false),lastPublish=-math.huge,lastAction={},holding=false}
 local root=C.Root or "Inv++/fleet" local now=C.Now or os.time local clock=C.Clock or os.clock
 local function place() return C.Place and C.Place() or game.PlaceId end
 local function jobId() return C.Job and C.Job() or game.JobId end
 if not isfolder(root) then makefolder(root) end
 local function read(path)
  if not isfile(path) then return nil end
  local ok,value=pcall(function() return Http:JSONDecode(readfile(path)) end)
  if ok and type(value)=="table" then return value end
  return nil,"Unreadable coordination file"
 end
 local function write(path,value)
  assert(F.alive and (not C.App or getgenv().InvPlus==C.App),"Fleet instance was replaced")
  writefile(path,Http:JSONEncode(value))
 end
 local configPath=root.."/config.json" local jobPath=root.."/job.json"
 local function defaults() return {version=1,automatic=false,includeExisting=true,since=now(),roster={},dungeon="Auto",difficulty="Auto",hardcore=false} end
 F.config=read(configPath) or defaults()
 if not isfile(configPath) then write(configPath,F.config) end
 function F.reload()
  local config,err=read(configPath)
  if not config or config.version~=1 or type(config.roster)~="table" then F.status=err or "Invalid fleet configuration" return false end
  F.config=config return true
 end
 local function registered(id) for _,m in ipairs(F.config.roster) do if m.id==id then return m end end end
 local function memberPath(id) return root.."/member_"..id..".json" end
 local function worn(item)
  if type(item.equipped)=="table" then for _,key in ipairs({"q","e","q2","e2"}) do if item.equipped[key] then return true end end return false end
  return item.equipped==true
 end
 local function find(id) for key,r in pairs(A.index) do if r.item.UniqueItemID==id then return r,tonumber(key:match(":(%d+)$")) end end end
 local function classOf(r)
  if r.kind=="ability" then return A.AutoEquip.spellClass(r) end
  if r.kind~="weapon" then local entry=A.entry(r.item.name,r.kind) local c=entry and tostring(entry.c):lower() or ""
   if c:find("guardian",1,true) then return "Guardian" elseif c:find("mage",1,true) then return "Mage" elseif c:find("war",1,true) then return "Warrior" end
  end
  return (tonumber(r.item.physicalDamage or r.item.physicalPower) or 0)>=(tonumber(r.item.spellPower) or 0) and "Warrior" or "Mage"
 end
 function F.item(r)
  local i=r.item local class=classOf(r) if not class then return nil end
  local field=class=="Guardian" and "health" or class=="Mage" and "spellPower" or r.kind=="weapon" and (i.physicalDamage~=nil and "physicalDamage" or "physicalPower") or "physicalPower"
  local value
  if r.kind=="ability" then value=tonumber(i.levelReq)
  elseif tonumber(i.currentUpgrade) and tonumber(i.maxUpgrades) and tonumber(i[field]) then value=A.potential(i[field],math.max(0,i.maxUpgrades-i.currentUpgrade)) end
  if not value or type(i.UniqueItemID)~="string" then return nil end
  local h=A.History.store.items[i.UniqueItemID]
  return {uid=i.UniqueItemID,name=i.name,kind=r.kind,class=class,field=field,value=value,level=tonumber(i.levelReq) or math.huge,equipped=worn(i),locked=i.locked==true,tag=A.Review.getTag(i.UniqueItemID),rarity=i.rarity,image=i.imageId,droppedAt=h and h.droppedAt,confirmed=h and h.acquisition=="drop" and h.confirmation=="reward-inventory-match"}
 end
 function F.isLobby(place)
  local ok,value=pcall(function() return require(RS.Utility.PlaceManager).GetPlaceName(place) end)
  return ok and (value=="Lobby" or value=="100+")
 end
 function F.snapshot()
  local items={}
  for _,r in pairs(A.index) do local item=F.item(r) if item then table.insert(items,item) end end
  local weapon=A.equipped("weapon")
  return {version=1,id=P.UserId,name=P.Name,nonce=F.nonce,at=now(),place=place(),job=jobId(),lobby=F.isLobby(place()),class=A.AutoEquip.class(),weaponClass=weapon and classOf(weapon),level=A.AutoEquip.level(),items=items,status=F.status,activeJob=F.activeJob,appliedJob=F.receivedApplied,holding=F.holding,fault=F.fault,inventoryAt=F.inventoryAt or now()}
 end
 function F.publish(force)
  if not registered(P.UserId) then return end
  if not force and clock()-F.lastPublish<3 then return end
  F.lastPublish=clock() write(memberPath(P.UserId),F.snapshot())
 end
 function F.members()
  local members={}
  for _,m in ipairs(F.config.roster) do
   local data=read(memberPath(m.id))
   if data and data.version==1 and data.id==m.id and type(data.items)=="table" and type(data.level)=="number" and type(data.class)=="string" and type(data.nonce)=="string" and now()-(data.at or 0)<=25 then table.insert(members,data) end
  end
  table.sort(members,function(a,b) return a.id<b.id end) return members
 end
 local function best(member,kind,class,equippedOnly)
  local value=0
  for _,i in ipairs(member.items or {}) do if i.kind==kind and i.class==class and i.level<=member.level and (not equippedOnly or i.equipped) and i.value>value then value=i.value end end
  return value
 end
 function F.recipient(source,item,members)
  if item.equipped or item.locked or item.tag=="Keep" or not item.value or not item.class then return nil end
  local sourceClass=item.kind=="weapon" and source.class=="Guardian" and source.weaponClass or source.class
  if item.class==sourceClass and item.value>best(source,item.kind,item.class,true) then return nil end
  local recipient,gain
  for _,m in ipairs(members) do
   local targetClass=item.kind=="weapon" and m.class=="Guardian" and m.weaponClass or m.class
   if m.id~=source.id and targetClass==item.class and item.level<=m.level then
    local previous=best(m,item.kind,item.class,false)
    if item.value>previous then
     local delta=(item.value-previous)/math.max(1,previous)
     if not gain or delta>gain or delta==gain and m.id<recipient.id then recipient=m gain=delta end
    end
   end
  end
  return recipient,gain
 end
 function F.plan(members,existing)
  local plan
  for _,source in ipairs(members) do for _,item in ipairs(source.items) do
   if (existing or item.confirmed and (item.droppedAt or 0)>=F.config.since) then
    local recipient,gain=F.recipient(source,item,members)
    if recipient and (not plan or gain>plan.gain or gain==plan.gain and item.uid<plan.item.uid) then plan={source=source.id,target=recipient.id,item=item,gain=gain} end
   end
  end end return plan
 end
 function F.reserved(id) local job=F.job return job and job.stage~="complete" and job.stage~="failed" and job.item and job.item.uid==id end
 local function isMember(job,id) for _,m in ipairs(job.members or {}) do if m.id==id then return true end end end
 local function fire(name,...) assert(F.alive and (not C.App or getgenv().InvPlus==C.App),"Fleet instance was replaced") if C.Fire then return C.Fire(name,...) end local r=RS.remotes:FindFirstChild(name) assert(r and r:IsA("RemoteEvent"),name.." unavailable") r:FireServer(...) end
 local function invoke(name,...) assert(F.alive and (not C.App or getgenv().InvPlus==C.App),"Fleet instance was replaced") if C.Invoke then return C.Invoke(name,...) end local r=RS.remotes:FindFirstChild(name) assert(r and r:IsA("RemoteFunction"),name.." unavailable") return r:InvokeServer(...) end
 local function action(key,seconds,fn)
  if clock()-(F.lastAction[key] or -math.huge)<seconds then return false end
  F.lastAction[key]=clock() fn() return true
 end
 function F.trade(job)
  local root=C.TradeRoot or workspace:FindFirstChild("trading") if not root then return nil end
  for _,trade in ipairs(root:GetChildren()) do
   local source,target,foreign
   for _,v in ipairs(trade:GetChildren()) do if v:IsA("ObjectValue") and v.Value and v.Value:IsA("Player") then
    if v.Value.UserId==job.source then source=v elseif v.Value.UserId==job.target then target=v else foreign=true end
   end end
   if source and target and not foreign then return trade,source,target end
  end
 end
 function F.offers(folder)
  local offers={} local gold=0
  for _,v in ipairs(folder:GetChildren()) do
   if v.Name=="goldOffer" then gold=tonumber(v.Value) or math.huge
   elseif v:FindFirstChild("type") then table.insert(offers,{uid=v:GetAttribute("offeredItemID"),kind=v.type.Value,object=v}) end
  end return offers,gold
 end
 function F.validateOffers(job,sourceOffers,targetOffers,sourceGold,targetGold)
  return #sourceOffers==1 and sourceOffers[1].uid==job.item.uid and sourceOffers[1].kind==job.item.kind and #targetOffers==0 and sourceGold==0 and targetGold==0
 end
 function F.cancelTrade(job)
  if F.trade(job) and (P.UserId==job.source or P.UserId==job.target) then fire("changePlayerToNotBusyTrading") end
 end
 function F.fail(job,message)
  job.stage="failed" job.error=message job.updated=now() write(jobPath,job)
  F.config.automatic=false F.config.lastError=message write(configPath,F.config) F.status=message
 end
 function F.setAutomatic(enabled)
  F.reload() F.config.automatic=enabled==true F.config.since=now() F.config.changedAt=now() F.config.lastError=nil F.fault=nil write(configPath,F.config)
  if not enabled then local job=read(jobPath) if job and job.stage~="complete" and job.stage~="failed" then job.cancel=true write(jobPath,job) F.cancelTrade(job) end end
  F.status=enabled and "Watching for useful drops" or "Tracking only"
 end
 function F.configure(key,value)
  if key~="dungeon" and key~="difficulty" and key~="hardcore" and key~="includeExisting" then return end
  F.reload() F.config[key]=value write(configPath,F.config)
 end
 function F.destination(members)
  local minimum=math.huge for _,m in ipairs(members) do minimum=math.min(minimum,m.level) end
  local names=F.config.dungeon~="Auto" and {F.config.dungeon} or {"Gilded Skies","Northern Lands","Enchanted Forest","Aquatic Temple","Volcanic Chambers","Orbital Outpost","Steampunk Sewers","Ghastly Harbor","The Canals","Samurai Palace","The Underworld","King's Castle","Pirate Island","Winter Outpost","Desert Temple"}
  for _,name in ipairs(names) do
   local ok,stats=pcall(invoke,"getDungeonStats",name)
   if ok and type(stats)=="table" then
    local difficulties=F.config.difficulty~="Auto" and {F.config.difficulty} or {"Nightmare","Insane","Hard","Medium","Easy"}
    for _,difficulty in ipairs(difficulties) do local info=stats[difficulty] if type(info)=="table" and tonumber(info.levelReq) and info.levelReq<=minimum then return {name=name,difficulty=difficulty,level=info.levelReq,hardcore=F.config.hardcore==true} end end
   end
  end
  return nil
 end
 local function peer(members,id) for _,m in ipairs(members) do if m.id==id then return m end end end
 function F.newJob(plan,members)
  local destination=F.destination(members) if not destination then F.status="Choose a dungeon all clients can enter" return end
  local roster={} for _,m in ipairs(members) do table.insert(roster,{id=m.id,name=m.name}) end
  local job={version=1,id=Http:GenerateGUID(false),owner=P.UserId,ownerNonce=F.nonce,created=now(),updated=now(),stage="gather",source=plan.source,target=plan.target,item=plan.item,members=roster,destination=destination}
  write(jobPath,job) F.job=job return job
 end
 function F.lobby(job,members)
  if not F.isLobby(place()) then
   F.status="Returning to lobby for transfer"
   action(job.id..":return",20,function() fire("ReturnToLobbyEvent") end) return false
  end
  if not job.anchorJob then return false end
  if jobId()~=job.anchorJob or place()~=job.anchorPlace then
   F.status="Joining the fleet lobby"
   action(job.id..":rendezvous",20,function()
    if C.Teleport then C.Teleport(job.anchorPlace,job.anchorJob) else game:GetService("TeleportService"):TeleportToPlaceInstance(job.anchorPlace,job.anchorJob,P) end
   end) return false
  end
  return true
 end
 function F.workTrade(job,members)
  local trade,sourceOffer,targetOffer=F.trade(job)
  if not trade then
   if P.UserId==job.source then
    local target=game.Players:GetPlayerByUserId(job.target)
    if target then action(job.id..":invite",12,function() local response=invoke("sendTradeRequest",target) if response~="sent" and response~=nil then F.status="Trade request: "..tostring(response) end end) end
   elseif P.UserId==job.target and F.invite and F.invite.UserId==job.source then
    local sender=F.invite F.invite=nil
    action(job.id..":inviteaccept",4,function() invoke("acceptTradeRequest",sender) end)
   end
   return
  end
  local sourceItems,sourceGold=F.offers(sourceOffer) local targetItems,targetGold=F.offers(targetOffer)
  if #sourceItems==0 and #targetItems==0 and sourceGold==0 and targetGold==0 then
   if P.UserId==job.source then action(job.id..":offer",4,function()
    C.Inventory.fetch(true)
    local r,slot=find(job.item.uid) assert(r and slot and not worn(r.item),"Transfer item no longer available")
    local item=F.item(r) local mine=F.snapshot() local recipient=F.recipient(mine,item,members)
    assert(recipient and recipient.id==job.target,"Transfer is no longer an upgrade")
    fire("addItemToTradeFolder",r.kind,slot)
   end) end
   return
  end
  if not F.validateOffers(job,sourceItems,targetItems,sourceGold,targetGold) then
   F.status="Trade offer changed; transfer stopped" F.cancelTrade(job)
   if P.UserId==job.owner then F.fail(job,F.status) end return
  end
  local accepted=trade:FindFirstChild(P.Name.."Accepted")
  if accepted and accepted.Value==false and (P.UserId==job.source or P.UserId==job.target) then
   action(job.id..":accept",2,function() fire("playerAcceptTrade") end)
  end
  F.status="Verified offer · waiting for trade completion"
 end
 local function partyFor(name)
  local games=workspace:FindFirstChild("games") local folder=C.PartyRoot or games and games:FindFirstChild("inLobby")
  if folder then return folder:FindFirstChild(name) end
 end
 function F.workRequeue(job)
  local owner=registered(job.owner) if not owner then return end
  local party=partyFor(owner.name)
  if P.UserId==job.owner then
   if not party then
    action(job.id..":create",12,function()
     local d=job.destination
     local result=invoke("createLobby",d.name,d.difficulty,d.level,d.hardcore,true,false)
     if result~=true then F.status="Dungeon lobby was not created" end
    end) return
   end
   local private=party:FindFirstChild("mapName") private=private and private:FindFirstChild("private")
   for _,m in ipairs(job.members) do if m.id~=job.owner and private and not private:FindFirstChild(m.name) then action(job.id..":whitelist:"..m.id,3,function() fire("addPlayerToWhitelist",m.name) end) end end
  else
   local private=party and party:FindFirstChild("mapName") private=private and private:FindFirstChild("private")
   if party and private and private:FindFirstChild(P.Name) and not party:FindFirstChild(P.Name) then action(job.id..":join",5,function() invoke("joinDungeon",owner.name) end) end
  end
  if P.UserId==job.owner and party then
   for _,m in ipairs(job.members) do if not party:FindFirstChild(m.name) then F.status="Waiting for all clients to join" return end end
   for _,v in ipairs(party:GetChildren()) do if v.Name~="mapName" then local allowed=false for _,m in ipairs(job.members) do if m.name==v.Name then allowed=true end end if not allowed then F.fail(job,"Unexpected player joined the fleet queue") return end end end
   job.stage="departing" job.updated=now() job.startRequestedAt=now() job.startAttempts=(job.startAttempts or 0)+1 write(jobPath,job)
   fire("startDungeon") F.status="Returning to "..job.destination.name
  end
 end
 function F.recordTransfer(job)
  local log=read(root.."/history.json") or {jobs={}}
  for _,entry in ipairs(log.jobs) do if entry.id==job.id then return end end
  table.insert(log.jobs,{id=job.id,item=job.item.name,source=job.source,target=job.target,completed=now(),dungeon=job.destination.name,difficulty=job.destination.difficulty})
  while #log.jobs>50 do table.remove(log.jobs,1) end write(root.."/history.json",log)
 end
 function F.coordinate(job,members)
  if not job or job.stage=="complete" or job.stage=="failed" then
   if not F.config.automatic or #members<2 then return end
   -- Wait for every registered client; a disconnected account never triggers a partial transfer.
   if #members~=#F.config.roster then F.status="Waiting for all registered clients" return end
   local plan=F.plan(members,F.config.includeExisting~=false) if plan then F.newJob(plan,members) end return
  end
  if job.cancel or not F.config.automatic then F.cancelTrade(job) F.fail(job,"Transfer stopped") return end
  if now()-job.created>360 then F.cancelTrade(job) F.fail(job,"Transfer timed out; clients remain stopped") return end
  if #members~=#job.members then F.status="Waiting for disconnected client" return end
  for _,m in ipairs(members) do if m.fault and m.fault.job==job.id then F.cancelTrade(job) F.fail(job,"Client stopped: "..tostring(m.fault.message):sub(1,90)) return end end
  if job.owner~=P.UserId or job.ownerNonce~=F.nonce then job.owner=P.UserId job.ownerNonce=F.nonce job.updated=now() write(jobPath,job) end
  if job.stage=="gather" then
   if not job.anchorJob then local anchor=peer(members,job.owner) if anchor and anchor.lobby then job.anchorJob=anchor.job job.anchorPlace=anchor.place job.updated=now() write(jobPath,job) end return end
   for _,m in ipairs(members) do if not m.lobby or m.job~=job.anchorJob or m.activeJob~=job.id then return end end
   local source=peer(members,job.source) local target=peer(members,job.target) local item
   for _,i in ipairs(source.items) do if i.uid==job.item.uid then item=i break end end
   local recipient=item and F.recipient(source,item,members)
   if not recipient or recipient.id~=target.id then F.fail(job,"Transfer no longer improves recipient") return end
   job.stage="trade" job.updated=now() write(jobPath,job)
  elseif job.stage=="trade" then
   local source=peer(members,job.source) local target=peer(members,job.target) local donorHas,receiverHas=false,false
   for _,i in ipairs(source.items) do if i.uid==job.item.uid then donorHas=true end end
   for _,i in ipairs(target.items) do if i.uid==job.item.uid then receiverHas=true end end
   if not donorHas and receiverHas then job.stage="equip" job.updated=now() job.transferredAt=now() write(jobPath,job) end
  elseif job.stage=="equip" then
   local target=peer(members,job.target)
   if target and target.appliedJob==job.id then
    F.recordTransfer(job)
    local nextPlan=F.plan(members,F.config.includeExisting~=false)
    if nextPlan then F.newJob(nextPlan,members)
    else job.stage="requeue" job.updated=now() write(jobPath,job) end
   end
  elseif job.stage=="departing" then
   local destinationJob
   for _,m in ipairs(members) do if m.lobby then return end if destinationJob and destinationJob~=m.job then return end destinationJob=m.job end
   job.stage="complete" job.updated=now() write(jobPath,job)
   F.recordTransfer(job)
  end
 end
 function F.step()
  if getgenv().InvPlusHarvardBooting then return end
  if getgenv().InvPlusAdapterBooting then return end
  if not F.alive or not F.reload() or not registered(P.UserId) then return end
  if clock()-(F.lastRefresh or -math.huge)>=8 and not C.Inventory.busy then C.Inventory.fetch() F.lastRefresh=clock() F.inventoryAt=now() end
  if not F.alive or C.App and getgenv().InvPlus~=C.App then return end
  F.publish()
  local members=F.members() F.clients=members local job,err=read(jobPath) if err then F.status=err return end
  if members[1] and members[1].id==P.UserId then F.coordinate(job,members) job=read(jobPath) end
  F.job=job F.holding=job and isMember(job,P.UserId) and job.stage~="complete" and job.stage~="failed" or false
  F.activeJob=F.holding and job.id or nil
  getgenv().InvPlusFleetHold=F.holding
  if not F.holding then F.status=F.config.lastError or (getgenv().InvPlusHarvardContext and getgenv().InvPlusHarvardContext.InvPlusTransfers and getgenv().InvPlusHarvardContext.InvPlusTransfers.PartyCoordinator and getgenv().InvPlusHarvardContext.InvPlusTransfers.PartyCoordinator.status) or (F.config.automatic and "Watching for useful drops" or "Tracking only") return end
  if job.cancel or not F.config.automatic then F.cancelTrade(job) return end
  if #members~=#job.members then F.cancelTrade(job) F.status="Waiting for all fleet clients" return end
  if job.stage=="departing" then F.status="Waiting for the group teleport" return end
  if not F.lobby(job,members) then return end
  if job.stage=="trade" then
   if P.UserId==job.source or P.UserId==job.target then F.workTrade(job,members) else F.status="Waiting for fleet transfer" end
   C.Inventory.fetch() F.inventoryAt=now() F.publish(true)
  elseif job.stage=="equip" then
   if P.UserId==job.target and F.receivedApplied~=job.id then
    local r,slot=find(job.item.uid)
    if r and slot then
     local previousGear=A.equipped(r.kind) local eligible=not previousGear or A.compare(r,previousGear) and (A.compare(r,previousGear).delta or -1)>0
     if eligible and r.kind~="ability" then invoke("equipItem",r.kind,slot)
     elseif r.kind=="ability" then local plan=A.AutoEquip.plan and A.AutoEquip.plan(job.item.uid) if plan and plan.abilitySlot then invoke("equipItem",r.kind,slot,plan.abilitySlot) end end
     C.Inventory.fetch(true)
     F.receivedApplied=job.id
     F.publish(true)
    end
   end
   F.status="Applying received gear before requeue"
  elseif job.stage=="requeue" then F.workRequeue(job)
  else F.status="Waiting for all clients in the lobby" end
 end
 function F.destroy()
  F.alive=false getgenv().InvPlusFleetHold=false
  for _,connection in ipairs(F.connections) do connection:Disconnect() end
 end
 local invite=RS.remotes:FindFirstChild("cloneTradeRequestGui")
 if invite then table.insert(F.connections,invite.OnClientEvent:Connect(function(sender) F.invite=sender end)) end
 if not C.NoWorker then task.spawn(function() while F.alive do
  local ok,err=pcall(F.step)
  if not ok then F.lastError=tostring(err) F.status="Fleet paused: "..tostring(err):sub(1,100) F.fault={job=F.activeJob,message=F.lastError} end
  task.wait(1)
 end end) end
 return F
end
end


Modules.autoequip=function()
return function(C)
 local A=C.Godpot local P=game.Players.LocalPlayer
 local Q={alive=true,queue={},queued={},status="Off",enabledAt=os.time()}
 local function prefs() return A.Extras.prefs end
 function Q.enabled() return prefs().autoEquipGear or prefs().autoEquipSpells end
 function Q.find(id)
  for key,r in pairs(A.index) do if r.item.UniqueItemID==id then local kind,slot=key:match("^(%a+):(%d+)$") if kind==r.kind then return r,tonumber(slot) end end end
 end
 local function classOf(r)
  if not r then return nil end
  if r.kind~="weapon" then
   local entry=A.entry(r.item.name,r.kind) local c=entry and tostring(entry.c):lower() or ""
   if c:find("guardian",1,true) then return "Guardian" elseif c:find("mage",1,true) then return "Mage" elseif c:find("war",1,true) then return "Warrior" end
  end
  local physical=tonumber(r.item.physicalDamage or r.item.physicalPower) or 0
  return physical>=(tonumber(r.item.spellPower) or 0) and "Warrior" or "Mage"
 end
 function Q.class()
  local selected=prefs().autoEquipClass
  if selected=="Mage" or selected=="Warrior" or selected=="Guardian" then return selected end
  local counts={}
  for _,kind in ipairs({"chest","helmet"}) do local c=classOf(A.equipped(kind)) if c then counts[c]=(counts[c] or 0)+1 end end
  for _,c in ipairs({"Mage","Warrior","Guardian"}) do if counts[c]==2 then return c end end
  return classOf(A.equipped("weapon"))
 end
 function Q.level()
  if C.Level then return C.Level() end
  local stats=P:FindFirstChild("leaderstats") local level=stats and stats:FindFirstChild("Level")
  return level and tonumber(level.Value)
 end
 local function equipped(r)
  local e=r.item.equipped
  if type(e)=="table" then for _,slot in ipairs({"q","e","q2","e2"}) do if e[slot] then return true end end return false end
  return e==true
 end
 function Q.spellClass(r)
  local d=tostring(r.item.description or ""):lower()
  for _,word in ipairs({"heal","boost","speed","taunt","invulner","shield","reduc","movement"}) do if d:find(word,1,true) then return nil end end
  if d:find("scales with spell power",1,true) then return "Mage" end
  if d:find("scales with physical",1,true) then return "Warrior" end
 end
 function Q.plan(id)
  local r,slot=Q.find(id)
  if not r or not slot or equipped(r) then return nil end
  local level=Q.level() if not level or (tonumber(r.item.levelReq) or math.huge)>level then return nil end
  local class=Q.class() if not class then return nil end
  if r.kind=="ability" then
   if not prefs().autoEquipSpells or Q.spellClass(r)~=class then return nil end
   local slots={}
   for _,other in pairs(A.index) do if other.kind=="ability" and type(other.item.equipped)=="table" then for _,key in ipairs({"q","e"}) do if other.item.equipped[key] then slots[key]=other end end end end
   local target,weakest
   for _,key in ipairs({"q","e"}) do
    local worn=slots[key]
    if not worn then target=key break end
    if Q.spellClass(worn)==class and tonumber(worn.item.levelReq) and r.item.levelReq>worn.item.levelReq then
     if not weakest or worn.item.levelReq<weakest then target=key weakest=worn.item.levelReq end
    end
   end
   if target then return {record=r,slot=slot,abilitySlot=target,class=class} end
   return nil
  end
  if not prefs().autoEquipGear or not ({weapon=true,helmet=true,chest=true})[r.kind] then return nil end
  -- Guardian armor is selected for health; its weapon keeps the current damage class.
  local gearClass=class
  if r.kind=="weapon" and class=="Guardian" then gearClass=classOf(A.equipped("weapon")) if not gearClass then return nil end end
  if classOf(r)~=gearClass then return nil end
  local field=gearClass=="Guardian" and "health" or gearClass=="Mage" and "spellPower" or r.kind=="weapon" and (r.item.physicalDamage~=nil and "physicalDamage" or "physicalPower") or "physicalPower"
  local function potential(item)
   local current,maximum=tonumber(item.currentUpgrade),tonumber(item.maxUpgrades)
   if not current or not maximum or maximum<current or not tonumber(item[field]) then return nil end
   return A.potential(item[field],maximum-current)
  end
  local value=potential(r.item) if not value then return nil end
  local worn=A.equipped(r.kind) local previous=worn and potential(worn.item)
  if worn and (not previous or value<=previous) then return nil end
  return {record=r,slot=slot,class=gearClass,field=field,value=value,previous=previous}
 end
 function Q.enqueue(id)
  if type(id)~="string" or Q.queued[id] or #Q.queue>=128 then return end
  Q.queued[id]=true table.insert(Q.queue,id)
 end
 function Q.onDrop(id,entry)
  if not Q.alive or not Q.enabled() or not entry or entry.acquisition~="drop" or entry.confirmation~="reward-inventory-match" or (entry.droppedAt or 0)<Q.enabledAt then return end
  Q.enqueue(id)
 end
 function Q.settingsChanged()
  Q.enabledAt=os.time() table.clear(Q.queue) table.clear(Q.queued)
  Q.status=Q.enabled() and "Watching for better drops" or "Off"
 end
 function Q.blocked()
  if A.Fleet and A.Fleet.holding then return true end
  local trading=P:FindFirstChild("busyTrading")
  if trading and trading.Value or C.Inventory and C.Inventory.busy then return true end
  if A.Review then for _,sale in pairs(A.Review.sales) do if sale.pending then return true end end end
  return false
 end
 function Q.step()
  if getgenv().InvPlusHarvardBooting then return end
  if not Q.alive or not Q.enabled() or Q.busy or #Q.queue==0 or Q.blocked() then return false end
  Q.busy=true
  local id=table.remove(Q.queue,1) Q.queued[id]=nil
  local ok,err=pcall(function()
   if C.Inventory then C.Inventory.fetch(true) end
   if not Q.alive or not Q.enabled() or Q.blocked() then Q.enqueue(id) return end
   local plan=Q.plan(id) if not plan then return end
   local remote=game.ReplicatedStorage.remotes:FindFirstChild("equipItem")
   if not C.Equip and (not remote or not remote:IsA("RemoteFunction")) then Q.status="Equip unavailable" return end
   Q.status="Equipping "..plan.record.item.name
   local result
   if C.Equip then result=C.Equip(plan.record.kind,plan.slot,plan.abilitySlot)
   elseif plan.abilitySlot then result=remote:InvokeServer(plan.record.kind,plan.slot,plan.abilitySlot)
   else result=remote:InvokeServer(plan.record.kind,plan.slot) end
   if C.Inventory then C.Inventory.fetch(true) end
   local fresh=Q.find(id) local confirmed=fresh and (plan.abilitySlot and type(fresh.item.equipped)=="table" and fresh.item.equipped[plan.abilitySlot] or not plan.abilitySlot and fresh.item.equipped==true)
   Q.status=confirmed and ("Equipped "..plan.record.item.name) or result==false and "Server declined equip" or "Equip not confirmed"
  end)
  Q.busy=false if not ok then Q.status="Could not equip item" Q.lastError=tostring(err) end
  return ok
 end
 function Q.destroy() Q.alive=false table.clear(Q.queue) end
 if Q.enabled() then Q.status="Watching for better drops" end
 if not C.NoWorker then task.spawn(function() while Q.alive do Q.step() task.wait(.75) end end) end
 return Q
end
end

Modules.review=function()
-- Local item labels and a native-styled loot review view.
return function(C)
 local A=C.Godpot local P=game:GetService("Players").LocalPlayer
 local UIS=game:GetService("UserInputService") local Http=game:GetService("HttpService")
 local templates=game.ReplicatedStorage.ui
 -- Keep private copies of the audited DQR assets. Optional injected templates
 -- are not available in every instance, so they must never be a dependency.
 local bar=templates:FindFirstChild("itemFilterBar")
 local dropdown=bar and bar:FindFirstChild("sortDropdown")
 local option=dropdown and dropdown:FindFirstChild("optionTemplate")
 local nativeOption
 if option and option:FindFirstChild("label") and option:FindFirstChild("button") then nativeOption=option:Clone() else
  nativeOption=Instance.new("ImageLabel") nativeOption.Name="optionTemplate" nativeOption.BackgroundTransparency=1
  nativeOption.Image="rbxassetid://2260429633" nativeOption.ScaleType=Enum.ScaleType.Slice nativeOption.SliceCenter=Rect.new(12,12,13,13) nativeOption.ImageColor3=Color3.fromRGB(52,52,52)
  local title=Instance.new("TextLabel") title.Name="label" title.BackgroundTransparency=1 title.Font=Enum.Font.Cartoon title.TextScaled=true title.TextStrokeTransparency=0 title.TextXAlignment=Enum.TextXAlignment.Left title.TextColor3=Color3.new(1,1,1) title.Parent=nativeOption
  local button=Instance.new("TextButton") button.Name="button" button.BackgroundTransparency=1 button.Text="" button.Parent=nativeOption
 end
 local R={alive=true,store={version=1,items={}},markers={},connections={},rowConnections={},open=false,revision=0,limit=30}
 local allowed={Keep=true,Trade=true}
 local colors={Keep=Color3.fromRGB(118,180,107),Trade=Color3.fromRGB(255,185,98),Sell=Color3.fromRGB(242,105,105)}
 R.sales={}
 local identitySales=true
 pcall(function()
  local place=require(game.ReplicatedStorage.Utility.PlaceManager).GetPlaceName(game.PlaceId)
  identitySales=place~="Level"
 end)
 if C.IdentitySales~=nil then identitySales=C.IdentitySales end
 function R.sellTarget(id)
  if type(id)~="string" then return nil,"Unavailable" end
  for key,record in pairs(A.index) do
   if record.item.UniqueItemID==id then
    local kind,number=key:match("^(%a+):(%d+)$")
    if not ({weapon=true,ability=true,chest=true,helmet=true})[kind] or kind~=record.kind or not tonumber(number) then return nil,"Unavailable" end
    local equipped=record.item.equipped
    if equipped==true or type(equipped)=="table" and (equipped.q or equipped.e or equipped.q2 or equipped.e2) then return nil,"Equipped" end
    if record.item.locked==true then return nil,"Locked" end
    local payload={weapon={},ability={},chest={},helmet={}}
    payload[kind][1]=identitySales and (tostring(tonumber(number))..":"..id) or tonumber(number)
    return payload,record
   end
  end
  return nil,"Not owned"
 end
 function R.sell(id)
  if A.Fleet and (A.Fleet.holding or A.Fleet.reserved(id)) then return false end
  if type(id)~="string" or not R.alive or R.sales[id] and R.sales[id].pending then return false end
  if A.AutoEquip and A.AutoEquip.busy then return false end
  local payload,reason=R.sellTarget(id)
  if not payload then R.sales[id]={text=reason} R.feedSignature=nil return false end
  local trading=P:FindFirstChild("busyTrading")
  if trading and trading.Value then R.sales[id]={text="Trading"} R.feedSignature=nil return false end
  local remote=game.ReplicatedStorage.remotes:FindFirstChild("sellItemEvent")
  if not C.SendSell and (not remote or not remote:IsA("RemoteEvent")) then R.sales[id]={text="Unavailable"} R.feedSignature=nil return false end
  local state={pending=true,text="Selling…"} R.sales[id]=state R.feedSignature=nil
  local ok=pcall(function() if C.SendSell then C.SendSell(payload) else remote:FireServer(payload) end end)
  if not ok then state.pending=false state.text="Failed" R.feedSignature=nil return false end
  -- Fire only once. Inventory refreshes confirm removal; they never retry a sale.
  for _,delay in ipairs({.35,2.5,6}) do
   (C.After or task.delay)(delay,function()
    if not R.alive or R.sales[id]~=state or not state.pending then return end
    if C.Inventory then C.Inventory.fetch(true) end
    if not R.alive then return end
    local owned=false for _,record in pairs(A.index) do if record.item.UniqueItemID==id then owned=true break end end
    if not owned then state.pending=false state.text="Sold" elseif delay==6 then state.pending=false state.text="Not sold" end
    R.feedSignature=nil
   end)
  end
  return true
 end
 R.path="Inv++/item_tags_"..P.UserId..".json"
 if isfile(R.path) then
  local ok,data=pcall(function() return Http:JSONDecode(readfile(R.path)) end)
  if ok and type(data)=="table" and data.version==1 and type(data.items)=="table" then R.store=data else R.readError="Invalid saved item tags" warn("[Inv++] "..R.readError) end
 end
 local function uid(record) return record and type(record.item.UniqueItemID)=="string" and record.item.UniqueItemID or nil end
 function R.getTag(id) local entry=id and R.store.items[id] return entry and allowed[entry.tag] and entry.tag or nil end
 function R.save()
  if not R.dirty or R.readError then return end
  local ok,err=pcall(function() writefile(R.path,Http:JSONEncode(R.store)) end)
  if ok then R.dirty=false else R.saveError=tostring(err) end
 end
 function R.setTag(id,tag)
  if type(id)~="string" or id=="" or tag~=nil and not allowed[tag] then return false end
  local entry=R.store.items[id] or {} R.store.items[id]=entry
  entry.tag=entry.tag~=tag and tag or nil entry.reviewedAt=os.time()
  R.dirty=true R.revision+=1 R.save()
  if A.Sorting then A.Sorting.apply() end
  return true
 end
 local fields={"UniqueItemID","name","rarity","imageId","levelReq","currentUpgrade","maxUpgrades","physicalDamage","physicalPower","spellPower","health","description"}
 function R.sync()
  local changed=false
  for _,record in pairs(A.index) do
   local id=uid(record) local entry=id and A.History.store.items[id]
   if entry then
    if not entry.snapshot then entry.snapshot={kind=record.kind,item={}} changed=true end
    entry.snapshot.kind=record.kind
    for _,key in ipairs(fields) do
     local value=record.item[key]
     if type(value)=="string" or type(value)=="number" or value==nil then
      if entry.snapshot.item[key]~=value then entry.snapshot.item[key]=value changed=true end
     end
    end
   end
  end
  if changed then A.History.changed() end
 end
 function R.entries(tag)
  local owned={} for _,record in pairs(A.index) do local id=uid(record) if id then owned[id]=record end end
  local entries={}
  for id,history in pairs(A.History.store.items) do
   if history.droppedAt and (not tag or R.getTag(id)==tag) and (not R.sessionOnly or history.droppedAt>=A.SessionStartedAt and history.acquisition~="reward") then
    table.insert(entries,{uid=id,history=history,record=owned[id] or history.snapshot,owned=owned[id]~=nil})
   end
  end
  table.sort(entries,function(a,b) if a.history.droppedAt~=b.history.droppedAt then return a.history.droppedAt>b.history.droppedAt end return a.uid<b.uid end)
  return entries
 end
 local function shown(object)
  while object and object~=P.PlayerGui do
   if object:IsA("GuiObject") and not object.Visible then return false end
   if object:IsA("ScreenGui") and not object.Enabled then return false end
   object=object.Parent
  end return true
 end
 local function point() local mouse=UIS:GetMouseLocation() local inv=P.PlayerGui:FindFirstChild("inventory") if inv and not inv.IgnoreGuiInset then mouse-=game:GetService("GuiService"):GetGuiInset() end return mouse end
 local function inside(object,p)
  local pos,size=object.AbsolutePosition,object.AbsoluteSize
  return p.X>=pos.X and p.X<=pos.X+size.X and p.Y>=pos.Y and p.Y<=pos.Y+size.Y
 end
 local function overlap(a,b)
  local p,s,q,t=a.AbsolutePosition,a.AbsoluteSize,b.AbsolutePosition,b.AbsoluteSize
  return p.X<q.X+t.X and p.X+s.X>q.X and p.Y<q.Y+t.Y and p.Y+s.Y>q.Y
 end
 local function label(parent,name,text,font,pos,size,max)
  local l=Instance.new("TextLabel") l.Name=name l.BackgroundTransparency=1 l.BorderSizePixel=0
  l.Font=font l.Text=text l.TextColor3=Color3.fromRGB(235,235,235) l.TextXAlignment=Enum.TextXAlignment.Left
  l.TextScaled=true l.TextStrokeTransparency=1 l.Position=pos l.Size=size l.ZIndex=parent.ZIndex+2 l.Parent=parent
  local c=Instance.new("UITextSizeConstraint") c.MinTextSize=10 c.MaxTextSize=max or 18 c.Parent=l return l
 end
 local function panel(parent,name,color,z)
  local f=nativeOption:Clone() f:ClearAllChildren()
  f.Visible=true f.SizeConstraint=Enum.SizeConstraint.RelativeXY f.AutomaticSize=Enum.AutomaticSize.None f.ClipsDescendants=false
  f.Name=name f.ImageColor3=color or Color3.fromRGB(52,52,52) f.ImageTransparency=0 f.BackgroundTransparency=1 f.AnchorPoint=Vector2.zero f.Rotation=0 f.ZIndex=z or 30 f.Parent=parent return f
 end
 local function action(parent,name,text,pos,size,callback,connections)
  local row=panel(parent,name,Color3.fromRGB(52,52,52),parent.ZIndex+1) row.Position=pos row.Size=size
  local textTemplate=nativeOption.label
  local title=textTemplate:Clone() title:ClearAllChildren() title.Name="label" title.Visible=true title.SizeConstraint=Enum.SizeConstraint.RelativeXY title.AutomaticSize=Enum.AutomaticSize.None title.Text=text title.TextStrokeTransparency=textTemplate.TextStrokeTransparency
  title.TextColor3=colors[text] or Color3.fromRGB(235,235,235) title.Position=UDim2.fromScale(.07,.1) title.Size=UDim2.fromScale(.86,.8) title.ZIndex=row.ZIndex+1 title.Parent=row
  local limit=Instance.new("UITextSizeConstraint") limit.MinTextSize=10 limit.MaxTextSize=18 limit.Parent=title
  local button=nativeOption.button:Clone() button:ClearAllChildren() button.Name="Action" button.Visible=true button.Active=true button.Interactable=true button.SizeConstraint=Enum.SizeConstraint.RelativeXY button.AutomaticSize=Enum.AutomaticSize.None button.Position=UDim2.fromScale(0,0) button.Size=UDim2.fromScale(1,1) button.AnchorPoint=Vector2.zero button.ZIndex=row.ZIndex+3 button.Parent=row
  table.insert(connections,button.Activated:Connect(callback))
  table.insert(connections,button.MouseEnter:Connect(function() row.ImageColor3=Color3.fromRGB(70,70,70) end))
  table.insert(connections,button.MouseLeave:Connect(function() row.ImageColor3=Color3.fromRGB(52,52,52) end))
  return row,title
 end
 function R.closeSellConfirm()
  R.confirmUid=nil
  for _,connection in ipairs(R.confirmConnections or {}) do connection:Disconnect() end R.confirmConnections={}
  local modal=R.sellConfirm R.sellConfirm=nil
  if modal then modal:Destroy() end
 end
 function R.confirmSale()
  local id=R.confirmUid
  R.closeSellConfirm()
  if not id then return false end
  return R.sell(id)
 end
 function R.requestSell(id)
  if A.Fleet and (A.Fleet.holding or A.Fleet.reserved(id)) then return false end
  if type(id)~="string" or not R.alive or R.sales[id] and R.sales[id].pending then return false end
  local payload,record=R.sellTarget(id)
  if not payload then R.sales[id]={text=record} R.feedSignature=nil return false end
  R.closeSellConfirm() R.hideMenu()
  local template=templates:FindFirstChild("sellConfirm")
  if not template then R.sales[id]={text="No dialog"} R.feedSignature=nil return false end
  local modal=template:Clone() modal.Name="InvPlusSellConfirm"
  for _,desc in ipairs(modal:GetDescendants()) do if desc:IsA("LuaSourceContainer") then desc:Destroy() end end
  local frame=modal.Frame.Frame
  local amount=A.integer and A.integer(record.item.sellPrice or 0) or tostring(record.item.sellPrice or 0)
  local message="Sell "..tostring(record.item.name or "this item").." for "..amount.." gold?"
  for _,name in ipairs({"chooseSlot","chooseSlot3d"}) do local text=frame:FindFirstChild(name) if text then text.Text=message text.TextWrapped=true text.TextScaled=true end end
  if modal:IsA("ScreenGui") then modal.DisplayOrder=math.max(modal.DisplayOrder,1000) modal.Enabled=true end
  R.confirmUid=id R.sellConfirm=modal R.confirmConnections={}
  table.insert(R.confirmConnections,frame.yes.TextButton.Activated:Connect(R.confirmSale))
  table.insert(R.confirmConnections,frame.no.TextButton.Activated:Connect(R.closeSellConfirm))
  table.insert(R.confirmConnections,UIS.InputBegan:Connect(function(input,processed) if not processed and (input.KeyCode==Enum.KeyCode.Escape or input.KeyCode==Enum.KeyCode.ButtonB) then R.closeSellConfirm() end end))
  modal.Parent=P.PlayerGui
  return true
 end
