 function R.pickRecord(p)
  if R.menu and inside(R.menu,p) then return nil end
  for card,state in pairs(R.markers) do
   if shown(card) and inside(card,p) then
    local valid=true local ancestor=card.Parent
    while ancestor and ancestor~=P.PlayerGui do
     if ancestor:IsA("GuiObject") and ancestor.ClipsDescendants and not inside(ancestor,p) then valid=false break end
     ancestor=ancestor.Parent
    end
    if valid then return state.record end
   end
  end
