 function R.renderFeed()
  if not R.open or not R.pane then return end
  local entries=R.entries(R.feedTag) local signature=tostring(R.revision)..":"..tostring(R.feedTag)..":"..tostring(R.sessionOnly)..":"..R.limit..":"..#entries..":"..tostring(A.Extras and A.Extras.gold())
  for _,entry in ipairs(entries) do local sale=R.sales[entry.uid] signature..=entry.uid..tostring(entry.owned)..tostring(entry.record and entry.record.item.currentUpgrade)..tostring(sale and sale.text) end
  if signature==R.feedSignature then return end R.feedSignature=signature
  for _,connection in ipairs(R.rowConnections) do connection:Disconnect() end table.clear(R.rowConnections)
