   R.summary.Text="Since "..os.date("%I:%M %p",A.SessionStartedAt).." · "..summary.count.." drops · Best "..(summary.best and A.text(summary.best) or "—").."\nMage "..summary.Mage.." · Warrior "..summary.Warrior.." · Guardian "..summary.Guardian.." · Other "..summary.Other
  end
