   local active=tag=="Session" and R.sessionOnly and not R.feedTag or tag=="All" and not R.sessionOnly and not R.feedTag or R.feedTag==tag
   button.ImageColor3=active and Color3.fromRGB(86,86,86) or Color3.fromRGB(52,52,52)
  end
