   local row=panel(R.scroller,"Drop_"..index,Color3.fromRGB(52,52,52),27) row.LayoutOrder=index row.Size=UDim2.new(1,-6,0,112)
   local tile=templates.inventorySlot:Clone() tile.Name="Item" tile.Position=UDim2.fromOffset(10,10) tile.Size=UDim2.fromOffset(80,80) tile.AnchorPoint=Vector2.zero tile.ZIndex=28 tile.Parent=row
   for _,desc in ipairs(tile:GetDescendants()) do if desc:IsA("GuiObject") then desc.ZIndex+=23 end end
   local button=tile:FindFirstChild("button") if button then button:Destroy() end
   if item then tile.filler.itemImage.Image=item.imageId or "" end
   local palette={common=Color3.fromRGB(152,152,152),uncommon=Color3.fromRGB(91,194,80),rare=Color3.fromRGB(75,77,195),epic=Color3.fromRGB(146,70,159),legendary=Color3.fromRGB(244,154,9),ultimate=Color3.fromRGB(255,0,0)}
   tile.ImageColor3=item and palette[tostring(item.rarity):lower()] or Color3.fromRGB(152,152,152)
   label(row,"Name",history.name or item and item.name or "Item",Enum.Font.Cartoon,UDim2.fromOffset(104,4),UDim2.new(1,-116,0,25),21)
   local percent,detail if record then percent,detail=A.compute(item,record.kind) end
   if record then A.shadeCard(tile,record,percent,detail,"review") end
   local quality=label(row,"Quality",percent and "Godpot "..A.text(percent) or item and tostring(item.rarity or "") or "Details unavailable",Enum.Font.Highway,UDim2.fromOffset(104,30),UDim2.fromOffset(120,20),16)
   if percent then quality.TextColor3=A.color(percent) end
   local comparison=record and A.compare(record,A.equipped(record.kind))
   local info=comparison and comparison.label.." "..A.compact(comparison.value) or ""
   if comparison and comparison.delta then info..="  ("..(comparison.delta>0 and "+" or "")..A.compact(comparison.delta)..")" end
   label(row,"Potential",info,Enum.Font.Highway,UDim2.fromOffset(230,30),UDim2.new(1,-242,0,20),16)
   local stamp=DateTime.fromUnixTimestamp(history.droppedAt):FormatLocalTime("MMM D · h:mm A","en-us")
   label(row,"Date",stamp.." · "..(history.source or "Unknown source")..(entry.owned and "" or " · no longer owned"),Enum.Font.Highway,UDim2.fromOffset(104,53),UDim2.new(1,-116,0,19),15)
   for i,choice in ipairs({"Keep","Trade"}) do
    local pick=choice
    local actionRow=action(row,"Tag_"..choice,choice,UDim2.new(.16+(i-1)*.28,0,0,79),UDim2.new(.265,0,0,26),function() R.setTag(entry.uid,pick) R.feedSignature=nil end,R.rowConnections)
    if tag==choice then actionRow.ImageColor3=Color3.fromRGB(86,86,86) end
   end
   local payload,blocked=R.sellTarget(entry.uid) local sale=R.sales[entry.uid]
   local text=sale and sale.text or (payload and "Sell" or blocked)
   local sell,title=action(row,"Sell",text,UDim2.new(.72,0,0,79),UDim2.new(.25,0,0,26),function() R.requestSell(entry.uid) end,R.rowConnections)
   local enabled=payload~=nil and not (sale and sale.pending)
   sell.Action.Active=enabled sell.Action.Interactable=enabled
   title.TextColor3=enabled and colors.Sell or Color3.fromRGB(160,160,160)
   if record then R.feedTargets[row]=record table.insert(R.rowConnections,row.InputBegan:Connect(function(input) if input.UserInputType==Enum.UserInputType.MouseButton2 then R.showMenu(record) end end)) end
  end
  if #entries>R.limit then
   local more=action(R.scroller,"OlderDrops","Show older drops",UDim2.new(),UDim2.new(1,-6,0,32),function() R.limit+=30 R.feedSignature=nil end,R.rowConnections)
   more.LayoutOrder=1000000
  end
 end
 function R.update()
  local inv=P.PlayerGui:FindFirstChild("inventory") local main=inv and inv:FindFirstChild("mainBackground") local inner=main and main:FindFirstChild("innerBackground")
  if not inner then return end R.build(inner) R.bindCards()
  if R.open then R.right.Visible=false R.pane.Visible=shown(main) R.renderFeed() else R.pane.Visible=false end
  if not shown(main) then R.hideMenu() end
 end
 function R.destroy()
  R.alive=false R.save() R.hideMenu() R.closeSellConfirm()
  if R.open and R.right and R.right.Parent then R.right.Visible=R.originalRightVisible~=false end
  for _,c in ipairs(R.connections) do c:Disconnect() end for _,c in ipairs(R.rowConnections) do c:Disconnect() end
  for _,state in pairs(R.markers) do for _,c in ipairs(state.connections) do c:Disconnect() end state.badge:Destroy() end
  if R.pane then R.pane:Destroy() end if R.launcher then R.launcher:Destroy() end
  nativeOption:Destroy()
 end
 table.insert(R.connections,UIS.InputBegan:Connect(function(input,processed)
  if input.UserInputType==Enum.UserInputType.MouseButton2 and not UIS:GetFocusedTextBox() then
   local p=Vector2.new(input.Position.X,input.Position.Y) local inv=P.PlayerGui:FindFirstChild("inventory") if inv and not inv.IgnoreGuiInset then p-=game:GetService("GuiService"):GetGuiInset() end R.openAt(p)
  elseif input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
   local p=Vector2.new(input.Position.X,input.Position.Y) local inv=P.PlayerGui:FindFirstChild("inventory") if inv and not inv.IgnoreGuiInset then p-=game:GetService("GuiService"):GetGuiInset() end
   if R.menu and not inside(R.menu,p) then R.hideMenu() end
  elseif not processed and input.KeyCode==Enum.KeyCode.Escape then R.hideMenu() end
 end))
 table.insert(R.connections,game:GetService("RunService").RenderStepped:Connect(function() if R.alive then local ok,err=pcall(R.updateMarkers) if not ok then R.lastError=tostring(err) end end end))
 return R
end
end

Modules.extras=function()
return function(C)
 local A,P=C.Godpot,game.Players.LocalPlayer
 local Http,UIS=game:GetService("HttpService"),game:GetService("UserInputService")
 local E={prefs={version=1,best=true,group=false,abbreviateStats=false,formatStatNumbers=true,rarityShading=true,rarityGradients=true,animatedGradients=false,saved={}},expanded={},markers={},connections={},menuConnections={}}
 E.path="Inv++/preferences_"..P.UserId..".json"
 if isfile(E.path) then
  local ok,data=pcall(function() return Http:JSONDecode(readfile(E.path)) end)
  if ok and type(data)=="table" and data.version==1 and type(data.saved)=="table" then
   E.prefs.best=data.best~=false E.prefs.group=data.group==true
   E.prefs.abbreviateStats=data.abbreviateStats==true E.prefs.formatStatNumbers=data.formatStatNumbers~=false E.prefs.rarityShading=data.rarityShading~=false E.prefs.rarityGradients=data.rarityGradients~=false E.prefs.animatedGradients=data.animatedGradients==true and E.prefs.rarityGradients
   E.prefs.autoEquipGear=data.autoEquipGear==true E.prefs.autoEquipSpells=data.autoEquipSpells==true E.prefs.autoEquipClass=({Auto=true,Mage=true,Warrior=true,Guardian=true})[data.autoEquipClass] and data.autoEquipClass or "Auto"
   for _,v in ipairs(data.saved) do
    if #E.prefs.saved<6 and type(v)=="table" and type(v.name)=="string" and type(v.query)=="string" then
     table.insert(E.prefs.saved,{name=v.name:sub(1,28),query=v.query,mode=v.mode,filters=type(v.filters)=="table" and v.filters or {rarity="all"}})
    end
   end
  else E.readError="Saved search file could not be read" end
 end
 function E.save()
  if E.readError then return false end
  local ok,err=pcall(function() writefile(E.path,Http:JSONEncode(E.prefs)) end)
  if not ok then E.saveError=tostring(err) end return ok
 end
 local function normalized(s) return tostring(s or ""):lower():gsub("%s+"," "):match("^%s*(.-)%s*$") end
 function E.family(record) return record.kind..":"..normalized(record.item.name) end
 function E.groupKey(record) return E.family(record)..":"..normalized(record.item.rarity) end
 function E.score(record) local c=A.compare(record,nil) return c and c.value or -math.huge end
 function E.better(a,b)
  if not b then return true end
  local x,y=E.score(a),E.score(b) if x~=y then return x>y end
  x,y=tonumber(a.item.currentUpgrade) or 0,tonumber(b.item.currentUpgrade) or 0 if x~=y then return x>y end
  return tostring(a.item.UniqueItemID or "")<tostring(b.item.UniqueItemID or "")
 end
 function E.rebuild()
  E.groups={} E.best={}
  for _,r in pairs(A.index) do
   local key=E.groupKey(r) E.groups[key]=(E.groups[key] or 0)+1
   if r.kind~="ability" then local family=E.family(r) if E.better(r,E.best[family]) then E.best[family]=r end end
  end
 end
 function E.isBest(r) local best=r and E.best[E.family(r)] return best and best.item.UniqueItemID==r.item.UniqueItemID or false end
 function E.filter(rows)
  if not E.prefs.group then return end
  local groups={}
  for _,row in ipairs(rows) do if row.card.Visible and row.record then
   local key=E.groupKey(row.record) local group=groups[key] or {} groups[key]=group group[#group+1]=row
  end end
  for key,group in pairs(groups) do if #group>1 and not E.expanded[key] then
   local best for _,row in ipairs(group) do if not best or E.better(row.record,best.record) then best=row end end
   for _,row in ipairs(group) do
    if A.Sorting.visibility[row.card]==nil then A.Sorting.visibility[row.card]=row.card.Visible end
    row.card.Visible=row==best
   end
  end end
  local count=0 for _,row in ipairs(rows) do if row.card.Visible then count+=1 end end
  A.Sorting.matchCount=count
  if A.Sorting.status then A.Sorting.status.Text=A.Sorting.error or tostring(count).." / "..tostring(#rows) end
 end
 local prefix={[0]=0} local cost=100
 for n=0,466 do
  prefix[n+1]=prefix[n]+math.floor(math.min(cost,100000))
  local nextCost=cost*1.06+50 cost=nextCost-cost>220 and cost+220 or nextCost
 end
 local function cumulative(n) n=math.max(0,math.floor(n)) return prefix[math.min(n,467)]+math.max(0,n-467)*100000 end
 function E.upgradeCost(item)
  local maximum=tonumber(item and item.maxUpgrades) local current=tonumber(item and item.currentUpgrade)
  if not maximum or not current then return nil end
  return math.max(0,cumulative(maximum)-cumulative(current))
 end
 function E.affordableUpgrades(item,gold)
  local current=math.max(0,math.floor(tonumber(item.currentUpgrade) or 0))
  local maximum=math.max(current,math.floor(tonumber(item.maxUpgrades) or current))
  local budget=math.max(0,tonumber(gold) or 0) local low,high=0,maximum-current
  while low<high do
   local mid=math.floor((low+high+1)/2)
   if cumulative(current+mid)-cumulative(current)<=budget then low=mid else high=mid-1 end
  end
  return low,cumulative(current+low)-cumulative(current)
 end
 function E.gold()
  local stats=P:FindFirstChild("leaderstats") local value=stats and stats:FindFirstChild("Gold")
  return value and tonumber(value.Value) or nil
 end
 function E.fitLabel(label,maximum)
  local bounds=label.AbsoluteSize local size=math.max(10,math.min(maximum,math.floor(bounds.Y*.92)))
  local measure=game:GetService("TextService") local width=math.max(1,bounds.X-2)
  while size>10 do
   local box=measure:GetTextSize(label.Text,size,label.Font,Vector2.new(label.TextWrapped and width or 10000,10000))
   if box.X<=width and box.Y<=bounds.Y then break end size-=1
  end
  label.TextScaled=false label.TextSize=size
 end
 function E.formatMenu()
  if not E.menu then return end
  if E.menuPage=="fleet" and A.Fleet then
   local body=E.menu:FindFirstChild("Options") local status=body and body:FindFirstChild("FleetStatus")
   if status then status.Text=A.Fleet.status.."\n"..#(A.Fleet.clients or {}).." / "..#A.Fleet.config.roster.." clients online" end
  end
  if E.menuPage=="autoequip" and A.AutoEquip then
   local body=E.menu:FindFirstChild("Options") local status=body and body:FindFirstChild("AutoEquipStatus")
   if status then status.Text=A.AutoEquip.status end
  end
  if E.menuPage=="webhook" and E.webhookStatus and A.Webhook then
   local W=A.Webhook local message=W.status.."\nQueued "..W.pendingCount().." · Sent this session "..W.sent
   if E.webhookStatus.Text~=message then E.webhookStatus.Text=message end
   E.webhookStatus.TextColor3=W.lastError and Color3.fromRGB(242,105,105) or W.config.enabled and Color3.fromRGB(135,232,121) or Color3.fromRGB(220,220,220)
  end
  for _,d in ipairs(E.menu:GetDescendants()) do if d:IsA("TextLabel") then
   E.fitLabel(d,d.Name=="Title" and 22 or d.Name=="SavedTitle" and 18 or 14)
  end end
 end
 function E.sessionStats(entries)
  local stats={count=0,Mage=0,Warrior=0,Guardian=0,Other=0}
  for _,entry in ipairs(entries) do
   stats.count+=1 local record=entry.record
   local class=record and A.Sorting.class(record) or "Other"
   stats[class or "Other"]=(stats[class or "Other"] or 0)+1
   local percent=record and A.compute(record.item,record.kind)
   if percent and (not stats.best or percent>stats.best) then stats.best=percent stats.bestName=record.item.name end
  end return stats
 end
 function E.capturePreset(name)
  local S=A.Sorting local predicates,err=S.compile(S.query) if not predicates then return nil,err end
  local filters={} for k,v in pairs(S.filters) do filters[k]=v end
  name=tostring(name or ""):match("^%s*(.-)%s*$"):sub(1,28)
  if name=="" then name=(S.query~="" and S.query or S.mode or "All items"):sub(1,28) end
  return {name=name,query=S.query,mode=S.mode,filters=filters}
 end
 function E.savePreset(name)
  if E.readError then return false,E.readError end
  local preset,err=E.capturePreset(name) if not preset then return false,err end
  for i,old in ipairs(E.prefs.saved) do if old.name==preset.name then E.prefs.saved[i]=preset return E.save() end end
  if #E.prefs.saved>=6 then return false,"Six saved searches max; remove one first" end
  table.insert(E.prefs.saved,preset) return E.save()
 end
 function E.loadPreset(preset)
  local S=A.Sorting local predicates,err=S.compile(preset.query) if not predicates then return false,err end
  S.restore() S.restoreVisibility() S.mode=table.find({"Mage","Warrior","Guardian","Highest Pot"},preset.mode) and preset.mode or nil
  S.filters={rarity="all"}
  for key,value in pairs(preset.filters or {}) do
   if key=="type" and table.find({"weapon","armor","ability"},value) or key=="rarity" and table.find({"all","common","uncommon","rare","epic","legendary","mythic","divine"},value) then S.filters[key]=value
   elseif (key=="new" or key=="upgrade") and type(value)=="boolean" then S.filters[key]=value end
  end
  S.setQuery(preset.query) if S.search then S.search.Text=preset.query end S.refreshButtons() return true
 end
 local function panel(parent,name,z)
  local f=Instance.new("ImageLabel") f.Name=name f.Image="rbxassetid://2260429633" f.ScaleType=Enum.ScaleType.Slice f.SliceCenter=Rect.new(12,12,13,13)
  f.BackgroundTransparency=1 f.ImageColor3=Color3.fromRGB(38,38,38) f.ZIndex=z f.Parent=parent return f
 end
 local function text(parent,name,value,font,z)
  local t=Instance.new("TextLabel") t.Name=name t.Text=value t.BackgroundTransparency=1 t.Font=font t.TextColor3=Color3.fromRGB(235,235,235)
  t.TextScaled=true t.TextWrapped=false t.TextXAlignment=Enum.TextXAlignment.Left t.ZIndex=z t.Parent=parent
  local cap=Instance.new("UITextSizeConstraint") cap.MinTextSize=10 cap.MaxTextSize=20 cap.Parent=t return t
 end
 local function action(parent,name,value,callback,connections)
  local row=panel(parent,name,parent.ZIndex+1) row.ImageColor3=Color3.fromRGB(65,65,65) row.Size=UDim2.new(1,-6,0,34)
  local button=Instance.new("TextButton") button.Name="Button" button.BackgroundTransparency=1 button.Position=UDim2.fromScale(.04,.08) button.Size=UDim2.fromScale(.92,.84)
  button.Text=value button.Font=Enum.Font.GothamBlack button.TextColor3=Color3.fromRGB(254,254,254) button.TextStrokeTransparency=0 button.TextScaled=true button.ZIndex=row.ZIndex+2 button.Parent=row
  local cap=Instance.new("UITextSizeConstraint") cap.MinTextSize=10 cap.MaxTextSize=18 cap.Parent=button
  table.insert(connections,button.Activated:Connect(callback)) return row,button
 end
 function E.closeMenu()
