     table.sort(client.items,function(a,b) if a.kind~=b.kind then return a.kind<b.kind end if a.value~=b.value then return a.value>b.value end return a.uid<b.uid end)
     for _,item in ipairs(client.items) do
      local details=item.name..(item.equipped and " · equipped" or "").."\n"..item.class.." · Lv "..item.level.." · "..(item.kind=="ability" and "Spell tier "..item.value or "Max "..A.compact(item.value))
      local label=text(body,"FleetItem",details,Enum.Font.Highway,703) label.Size=UDim2.new(1,-6,0,48) label.TextWrapped=true label.TextColor3=item.class=="Mage" and Color3.fromRGB(111,179,255) or item.class=="Warrior" and Color3.fromRGB(242,105,105) or Color3.fromRGB(135,232,121) add(label)
     end
    else local note=text(body,"ClientOffline","Client offline or inventory not yet published.",Enum.Font.Highway,703) note.Size=UDim2.new(1,-6,0,48) note.TextWrapped=true add(note) end
   else
    add(action(body,"FleetAutomatic","Automatic transfers: "..(F.config.automatic and "On" or "Off"),function() F.setAutomatic(not F.config.automatic) E.openMenu("fleet") end,E.menuConnections))
    add(action(body,"FleetExisting","Existing inventory: "..(F.config.includeExisting~=false and "On" or "Off"),function() F.configure("includeExisting",F.config.includeExisting==false) E.openMenu("fleet") end,E.menuConnections))
    add(action(body,"FleetDungeon","Dungeon: "..F.config.dungeon,function() local cycle={Auto="Gilded Skies",["Gilded Skies"]="Northern Lands",["Northern Lands"]="Auto"} F.configure("dungeon",cycle[F.config.dungeon] or "Auto") E.openMenu("fleet") end,E.menuConnections))
    add(action(body,"FleetDifficulty","Difficulty: "..F.config.difficulty,function() local cycle={Auto="Insane",Insane="Nightmare",Nightmare="Auto"} F.configure("difficulty",cycle[F.config.difficulty] or "Auto") E.openMenu("fleet") end,E.menuConnections))
    add(action(body,"FleetHardcore","Hardcore: "..(F.config.hardcore and "On" or "Off"),function() F.configure("hardcore",not F.config.hardcore) E.openMenu("fleet") end,E.menuConnections))
    local status=text(body,"FleetStatus",F.status,Enum.Font.Highway,703) status.Size=UDim2.new(1,-6,0,58) status.TextWrapped=true add(status)
    for _,m in ipairs(F.clients or {}) do local member=m add(action(body,"FleetClient_"..member.id,member.name.." · "..(member.class or "?").." · "..#member.items.." items",function() E.openMenu("fleet:"..member.id) end,E.menuConnections)) end
    local note=text(body,"FleetHelp","Includes existing inventory and new drops. Keeps useful gear and Keep-tagged items. Transfers exact item IDs between these clients, then requeues all together in a private dungeon. Automatic transfers start Off. Stop the toggle to cancel.",Enum.Font.Highway,703) note.Size=UDim2.new(1,-6,0,132) note.TextWrapped=true add(note)
   end
   E.positionMenu() E.formatMenu() return
  end
  if page=="autoequip" then
   add(action(body,"BackToTools","Back to Inventory Tools",function() E.openMenu() end,E.menuConnections))
   local function change(key,value) E.prefs[key]=value E.save() if A.AutoEquip then A.AutoEquip.settingsChanged() end E.openMenu("autoequip") end
   add(action(body,"AutoEquipGear","Best Gear: "..(E.prefs.autoEquipGear and "On" or "Off"),function() change("autoEquipGear",not E.prefs.autoEquipGear) end,E.menuConnections))
   add(action(body,"AutoEquipSpells","Higher-Level Spells: "..(E.prefs.autoEquipSpells and "On" or "Off"),function() change("autoEquipSpells",not E.prefs.autoEquipSpells) end,E.menuConnections))
   add(action(body,"AutoEquipClass","Class: "..(E.prefs.autoEquipClass or "Auto"),function() local nextClass={Auto="Mage",Mage="Warrior",Warrior="Guardian",Guardian="Auto"} change("autoEquipClass",nextClass[E.prefs.autoEquipClass or "Auto"] or "Auto") end,E.menuConnections))
   local note=text(body,"AutoEquipHelp","New drops only. Gear compares fully upgraded class stats. Spells use class and required level, replacing lower-level damage spells in Q/E. Healing, utility and equal-level spells stay equipped. No gold is spent.",Enum.Font.Highway,703) note.Size=UDim2.new(1,-6,0,126) note.TextWrapped=true add(note)
   local status=text(body,"AutoEquipStatus",A.AutoEquip and A.AutoEquip.status or "Off",Enum.Font.Highway,703) status.Size=UDim2.new(1,-6,0,42) status.TextWrapped=true add(status)
   E.positionMenu() E.formatMenu() return
  end
  local W=A.Webhook
  add(action(body,"FleetInventories","Connected Inventories",function() E.openMenu("fleet") end,E.menuConnections))
  add(action(body,"DropWebhook","Drop Webhook: "..(W and W.config.enabled and "On" or W and W.config.url~="" and "Off" or "Set up"),function() E.openMenu("webhook") end,E.menuConnections))
  add(action(body,"AutoEquip","Auto Equip Gear & Spells: "..((E.prefs.autoEquipGear or E.prefs.autoEquipSpells) and "On" or "Off"),function() E.openMenu("autoequip") end,E.menuConnections))
  add(action(body,"Grouping","Group duplicates: "..(E.prefs.group and "On" or "Off"),function() E.prefs.group=not E.prefs.group E.save() A.Sorting.apply() E.openMenu() end,E.menuConnections))
  add(action(body,"Best","Best-copy markers: "..(E.prefs.best and "On" or "Off"),function() E.prefs.best=not E.prefs.best E.save() E.openMenu() end,E.menuConnections))
  add(action(body,"RarityGradients","Rarity Gradients: "..(E.prefs.rarityGradients~=false and "On" or "Off"),function() E.prefs.rarityGradients=E.prefs.rarityGradients==false if not E.prefs.rarityGradients then E.prefs.animatedGradients=false end E.save() A.Review.feedSignature=nil E.openMenu() end,E.menuConnections))
  add(action(body,"AnimatedGradients","Animated Gradients: "..(E.prefs.animatedGradients and "On" or "Off"),function() E.prefs.animatedGradients=not E.prefs.animatedGradients if E.prefs.animatedGradients then E.prefs.rarityGradients=true end E.save() A.Review.feedSignature=nil if A.animateGradients then A.animateGradients(true) end E.openMenu() end,E.menuConnections))
  add(action(body,"RarityShading","Godpot Rarity Shading: "..(E.prefs.rarityShading~=false and "On" or "Off"),function() E.prefs.rarityShading=E.prefs.rarityShading==false E.save() A.Review.feedSignature=nil E.openMenu() end,E.menuConnections))
  add(action(body,"AbbreviateStats","Abbreviate Stats: "..(E.prefs.abbreviateStats and "On" or "Off"),function() E.prefs.abbreviateStats=not E.prefs.abbreviateStats E.save() E.openMenu() end,E.menuConnections))
  add(action(body,"FormatStatNumbers","Format Stat Numbers: "..(E.prefs.formatStatNumbers~=false and "On" or "Off"),function() E.prefs.formatStatNumbers=E.prefs.formatStatNumbers==false E.save() E.openMenu() end,E.menuConnections))
  add(action(body,"Session","Session loot",function() E.closeMenu() A.Review.sessionOnly=true A.Review.feedTag=nil A.Review.limit=30 A.Review.feedSignature=nil A.Review.setOpen(true) end,E.menuConnections))
  local note=text(body,"SessionNote","Tracking since "..os.date("%I:%M %p",C.App.SessionStartedAt).." · confirmed drops only",Enum.Font.Highway,703) note.Size=UDim2.new(1,-6,0,23) add(note)
  local heading=text(body,"SavedTitle","Saved searches",Enum.Font.Cartoon,703) heading.Size=UDim2.new(1,-6,0,28) add(heading)
  local input=Instance.new("TextBox") input.Name="PresetName" input.BackgroundColor3=Color3.fromRGB(52,52,52) input.BorderSizePixel=0 input.Font=Enum.Font.Highway input.TextColor3=Color3.new(1,1,1) input.TextSize=18 input.Text="" input.PlaceholderText="Name this search (optional)" input.ClearTextOnFocus=false input.Size=UDim2.new(1,-6,0,32) input.ZIndex=704 input.Parent=body add(input)
  add(action(body,"SaveSearch","Save current search",function() local ok,err=E.savePreset(input.Text) if ok then E.openMenu() else input.Text="" input.PlaceholderText=err or "Could not save" end end,E.menuConnections))
  for index,preset in ipairs(E.prefs.saved) do
   local saved= preset local row,load=action(body,"Preset_"..index,saved.name,function() local ok=E.loadPreset(saved) if ok then E.closeMenu() end end,E.menuConnections) add(row)
   load.Size=UDim2.fromScale(.82,.84)
   local remove=close:Clone() remove.Name="Remove" remove.Position=UDim2.new(1,-34,0,2) remove.Size=UDim2.fromOffset(28,28) remove.ZIndex=705 remove.Parent=row
   table.insert(E.menuConnections,remove.Activated:Connect(function() table.remove(E.prefs.saved,index) E.save() E.openMenu() end))
  end
  if #E.prefs.saved==0 then local empty=text(body,"EmptySaved","Save the current search, filters and sort together.",Enum.Font.Highway,703) empty.Size=UDim2.new(1,-6,0,30) add(empty) end
  E.positionMenu()
  E.formatMenu()
 end
 function E.buildWebhookPage(body,add)
  local W=A.Webhook if not W then return end
  add(action(body,"BackToTools","Back to Inventory Tools",function() E.openMenu() end,E.menuConnections))
  local caption=text(body,"WebhookCaption","Item art · Rarity colors · Complete drop stats",Enum.Font.Highway,703) caption.Size=UDim2.new(1,-6,0,28) add(caption)
  local status=text(body,"WebhookStatus","",Enum.Font.Highway,703) status.Size=UDim2.new(1,-6,0,54) status.TextWrapped=true E.webhookStatus=status add(status)
  local pendingURL
  local input=Instance.new("TextBox") input.Name="WebhookURL" input.BackgroundColor3=Color3.fromRGB(52,52,52) input.BorderSizePixel=0 input.Font=Enum.Font.Highway input.TextColor3=Color3.new(1,1,1) input.TextSize=16 input.Text="" input.PlaceholderText=W.config.url~="" and "Webhook saved · paste here to replace" or "Paste Discord webhook URL" input.ClearTextOnFocus=false input.MultiLine=false input.Size=UDim2.new(1,-6,0,36) input.ZIndex=704 input.Parent=body add(input)
  table.insert(E.menuConnections,input.FocusLost:Connect(function()
   local value=input.Text:match("^%s*(.-)%s*$")
   if value~="" then pendingURL=value input.Text="" input.PlaceholderText="URL entered · press Save & enable" end
  end))
  add(action(body,"SaveWebhook","Save & enable",function()
   local value=input.Text:match("^%s*(.-)%s*$")
   if value=="" then value=pendingURL or W.config.url end
   if W.configure(value) then E.openMenu("webhook") else E.formatMenu() end
  end,E.menuConnections))
  add(action(body,"EnableWebhook","Drop notifications: "..(W.config.enabled and "On" or "Off"),function() if W.setEnabled(not W.config.enabled) then E.openMenu("webhook") else E.formatMenu() end end,E.menuConnections))
  add(action(body,"WebhookANSI","ANSI colors: "..(W.config.ansi and "On" or "Off"),function() W.config.ansi=not W.config.ansi W.save() E.openMenu("webhook") end,E.menuConnections))
  add(action(body,"TestWebhook","Send test embed",function() W.sendTest() E.formatMenu() end,E.menuConnections))
  local note=text(body,"WebhookHelp","Posts newly confirmed dungeon drops. The test uses an owned item and is clearly marked TEST. URL is stored locally and hidden after entry.",Enum.Font.Highway,703) note.Size=UDim2.new(1,-6,0,64) note.TextWrapped=true add(note)
 end
 function E.positionMenu()
  if not E.menu or not E.anchor then return end
  local inv=P.PlayerGui.inventory local viewport=inv.AbsoluteSize local p=E.anchor.AbsolutePosition
  local height=math.min(E.menuPage=="webhook" and 470 or 420,viewport.Y-24) E.menu.Size=UDim2.fromOffset(math.min(E.menuPage=="webhook" and 400 or 360,viewport.X-24),height)
  E.menu.Position=UDim2.fromOffset(math.clamp(p.X+E.anchor.AbsoluteSize.X-E.menu.AbsoluteSize.X,8,math.max(8,viewport.X-E.menu.AbsoluteSize.X-8)),math.clamp(p.Y-height-8,8,math.max(8,viewport.Y-height-8)))
 end
 function E.build()
  local S=A.Sorting local bar=S.searchBar local face=bar and bar:FindFirstChild("Face") if not face then return end
  if E.anchor and E.anchor.Parent==face then return end
  if E.anchor then E.anchor:Destroy() end
  S.search.Size=UDim2.fromScale(.61,.8)
  local status=S.status status.Position=UDim2.fromScale(.80,.1) status.Size=UDim2.fromScale(.12,.8)
  local holder,button=action(face,"InvPlusToolsButton","Tools",function() if E.menu then E.closeMenu() else E.openMenu() end end,E.connections)
  holder.Position=UDim2.fromScale(.65,.06) holder.Size=UDim2.fromScale(.135,.88) holder.ZIndex=6 button.ZIndex=8 E.anchor=holder
 end
 local function shown(o)
  while o and o~=P.PlayerGui do if o:IsA("GuiObject") and not o.Visible or o:IsA("ScreenGui") and not o.Enabled then return false end o=o.Parent end return true
 end
 local function overlap(a,b)
  local p,s,q,t=a.AbsolutePosition,a.AbsoluteSize,b.AbsolutePosition,b.AbsoluteSize
  return p.X<q.X+t.X and p.X+s.X>q.X and p.Y<q.Y+t.Y and p.Y+s.Y>q.Y
 end
 function E.renderMarkers()
  local active={}
  for card,state in pairs(A.Review.markers) do
   local record=state.record local count=E.groups[E.groupKey(record)] or 1 local best=E.prefs.best and E.isBest(record)
   active[card]=true local marker=E.markers[card]
   if not marker then
    local duplicate=Instance.new("TextButton") duplicate.Name="InvPlusDuplicateCount" duplicate.BackgroundColor3=Color3.fromRGB(20,20,20) duplicate.BackgroundTransparency=.18 duplicate.BorderSizePixel=0 duplicate.Position=UDim2.fromScale(.04,.75) duplicate.Size=UDim2.fromScale(.29,.21) duplicate.Font=Enum.Font.Highway duplicate.TextScaled=true duplicate.TextColor3=Color3.fromRGB(235,235,235) duplicate.ZIndex=16 duplicate.Parent=card
    local cap=Instance.new("UITextSizeConstraint") cap.MinTextSize=8 cap.MaxTextSize=12 cap.Parent=duplicate
    local round=Instance.new("UICorner") round.CornerRadius=UDim.new(0,3) round.Parent=duplicate
    local bestLabel=text(card,"InvPlusBestCopy","BEST",Enum.Font.Cartoon,10) bestLabel.Position=UDim2.fromScale(.57,.04) bestLabel.Size=UDim2.fromScale(.39,.18) bestLabel.TextColor3=Color3.fromRGB(255,224,115) bestLabel.TextXAlignment=Enum.TextXAlignment.Right
    bestLabel.UITextSizeConstraint.MinTextSize=8 bestLabel.UITextSizeConstraint.MaxTextSize=11
    marker={count=duplicate,best=bestLabel,record=record} E.markers[card]=marker
    marker.connection=duplicate.Activated:Connect(function() if E.prefs.group then local key=E.groupKey(marker.record) E.expanded[key]=not E.expanded[key] A.Sorting.apply() end end)
   end
   marker.record=record marker.showCount=count>1 marker.showBest=best
   marker.count.Text="×"..count marker.count.Visible=count>1 marker.best.Visible=best marker.best.TextScaled=true
  end
  for card,marker in pairs(E.markers) do if not active[card] then marker.connection:Disconnect() marker.count:Destroy() marker.best:Destroy() E.markers[card]=nil end end
 end
 function E.occlude(occluders)
  E.formatMenu()
  if A.Review.summary and A.Review.summary.Visible then E.fitLabel(A.Review.summary,17) end
  for card,marker in pairs(E.markers) do
   for _,pair in ipairs({{marker.count,marker.showCount},{marker.best,marker.showBest}}) do
    local badge,visible=pair[1],pair[2] visible=visible and shown(card)
    if visible then for _,o in ipairs(occluders) do if overlap(badge,o) then visible=false break end end end
    if visible and E.menu and overlap(badge,E.menu) then visible=false end
    if visible and A.Review.menu and overlap(badge,A.Review.menu) then visible=false end
    badge.Visible=visible
   end
  end
 end
 function E.update()
  E.build() E.renderMarkers()
  if E.menu then if not E.anchor or not shown(E.anchor) then E.closeMenu() else E.positionMenu() E.formatMenu() end end
 end
 function E.destroy()
  E.closeMenu() for _,c in ipairs(E.connections) do c:Disconnect() end
  for _,m in pairs(E.markers) do m.connection:Disconnect() m.count:Destroy() m.best:Destroy() end
  if E.anchor then E.anchor:Destroy() end
 end
 table.insert(E.connections,UIS.InputBegan:Connect(function(input,processed)
  if input.KeyCode==Enum.KeyCode.Escape and not processed then E.closeMenu()
  elseif E.menu and (input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch) then
   local p=Vector2.new(input.Position.X,input.Position.Y) local inv=P.PlayerGui.inventory if not inv.IgnoreGuiInset then p-=game:GetService("GuiService"):GetGuiInset() end
   local a,b=E.menu.AbsolutePosition,E.menu.AbsoluteSize local x,y=E.anchor.AbsolutePosition,E.anchor.AbsoluteSize
   if not (p.X>=a.X and p.X<=a.X+b.X and p.Y>=a.Y and p.Y<=a.Y+b.Y) and not (p.X>=x.X and p.X<=x.X+y.X and p.Y>=x.Y and p.Y<=x.Y+y.Y) then E.closeMenu() end
  end
 end))
 E.rebuild() return E
end
end

Modules.webhook=function()
return function(C)
 local A,P=C.Godpot,game.Players.LocalPlayer
 local Http=game:GetService("HttpService")
 local prefix=C.StoragePrefix or "Inv++/webhook_"..P.UserId
 local W={alive=true,config={version=1,url="",enabled=false,ansi=true,enabledAt=0},outbox={version=1,items={}},art={},nextAt=0,sent=0,status="Paste a Discord webhook URL to begin."}
 W.path=prefix..".json" W.queuePath=prefix.."_outbox.json" W.artPath=prefix.."_art.json"
 local transport=C.Request or request or http_request or (http and http.request) or (syn and syn.request)
 local function clean(value,max)
  return tostring(value or ""):gsub("[%c]"," "):gsub("`","'"):sub(1,max or 180)
 end
 local function read(path)
  if not isfile(path) then return nil end
  local ok,data=pcall(function() return Http:JSONDecode(readfile(path)) end)
  return ok and type(data)=="table" and data or nil,not ok
 end
 function W.parseURL(value)
  local url=tostring(value or ""):match("^%s*(.-)%s*$")
  local core,query=url:match("^(.-)%?(.*)$") core=core or url
  core=core:gsub("^https://discordapp%.com/","https://discord.com/"):gsub("/api/v%d+/webhooks/","/api/webhooks/"):gsub("/+$","")
  local id,token=core:match("^https://discord%.com/api/webhooks/(%d+)/([%w_%-]+)$")
  if not id or #id<10 or #token<20 then return nil end
  local thread=query and query:match("^thread_id=(%d+)$")
  if query and not thread then return nil end
  return core..(thread and "?thread_id="..thread or ""),id..(thread and ":"..thread or "")
 end
 local config,bad=read(W.path)
 if config and config.version==1 then
  local url=W.parseURL(config.url)
  W.config.url=url or "" W.config.enabled=config.enabled==true and url~=nil
  W.config.ansi=config.ansi~=false W.config.enabledAt=tonumber(config.enabledAt) or os.time()
  W.status=url and (W.config.enabled and "Listening for new drops." or "Webhook saved; notifications paused.") or W.status
 elseif bad then W.readError=true W.status="Saved webhook settings could not be read." end
 local outbox,queueBad=read(W.queuePath)
 if outbox and outbox.version==1 and type(outbox.items)=="table" then
  for uid,job in pairs(outbox.items) do
   if type(uid)=="string" and type(job)=="table" and type(job.record)=="table" and type(job.record.item)=="table" and type(job.history)=="table" then
    job.uid=uid job.queuedAt=tonumber(job.queuedAt) or os.time()
    if job.state=="sending" then job.state="uncertain" W.status="A previous send was interrupted; it will not be repeated automatically." end
    if job.state=="queued" or job.state=="uncertain" or job.state=="failed" then W.outbox.items[uid]=job end
   end
  end
 elseif queueBad then W.queueReadError=true W.status="Saved delivery queue could not be read." end
 local art=read(W.artPath) if art and type(art.items)=="table" then W.art=art.items end
 function W.save()
  if W.readError then return false end
  local ok=pcall(function() writefile(W.path,Http:JSONEncode(W.config)) end)
  if not ok then W.status="Could not save webhook settings." W.lastError=W.status end return ok
 end
 function W.saveQueue()
  if W.queueReadError then return false end
  local ok=pcall(function() writefile(W.queuePath,Http:JSONEncode(W.outbox)) end)
  if not ok then W.status="Could not save the delivery queue." W.lastError=W.status end return ok
 end
 function W.configure(value)
  local url,key=W.parseURL(value)
  if not url then W.status="Paste a complete Discord webhook URL." W.lastError=W.status return false end
  if type(transport)~="function" then W.status="HTTP requests are unavailable in this executor." W.lastError=W.status return false end
  local oldUrl=W.config.url local wasEnabled=W.config.enabled
  W.readError=nil W.config.url=url W.config.enabled=true
  if url~=oldUrl or not wasEnabled then W.config.enabledAt=os.time() end
  for _,job in pairs(W.outbox.items) do if job.state=="queued" and job.destination~=key then job.state="failed" job.reason="Destination changed" end end
  W.lastError=nil W.status="Listening for new drops." W.saveQueue() return W.save()
 end
 function W.setEnabled(enabled)
  if enabled and not W.parseURL(W.config.url) then W.status="Save a webhook URL first." W.lastError=W.status return false end
  if enabled and type(transport)~="function" then W.status="HTTP requests are unavailable in this executor." W.lastError=W.status return false end
  if enabled and not W.config.enabled then W.config.enabledAt=os.time() end
  W.config.enabled=enabled==true W.status=enabled and "Listening for new drops." or "Notifications paused." W.lastError=nil
  if not enabled then for _,job in pairs(W.outbox.items) do if job.state=="queued" then job.state="failed" job.reason="Notifications paused" end end W.saveQueue() end
  return W.save()
 end
 function W.pendingCount()
  local count=0 for _,job in pairs(W.outbox.items) do if job.state=="queued" or job.state=="sending" then count+=1 end end return count
 end
 function W.assetID(image)
  local text=tostring(image or "")
  return text:match("^rbxassetid://(%d+)") or text:match("^rbxthumb://.-[?&]?id=(%d+)") or text:match("[?&]id=(%d+)") or text:match("^(%d+)$")
 end
 local function cdnURL(url)
  local host=type(url)=="string" and url:match("^https://([^/]+)/")
  return host and (host=="rbxcdn.com" or host:sub(-11)==".rbxcdn.com") or false
 end
 local function status(response) return type(response)=="table" and tonumber(response.StatusCode or response.Status or response.status_code) or nil end
 local function decode(response)
  local ok,data=pcall(function() return Http:JSONDecode(response.Body or response.body or "") end) return ok and type(data)=="table" and data or {}
 end
 local function header(response,wanted)
  for k,v in pairs(type(response.Headers or response.headers)=="table" and (response.Headers or response.headers) or {}) do if tostring(k):lower()==wanted:lower() then return tostring(v) end end
 end
 function W.resolveArt(image)
  if cdnURL(image) then return image end
  local id=W.assetID(image) if not id or type(transport)~="function" then return nil end
  local cached=W.art[id]
  if cached and tonumber(cached.expires) and cached.expires>os.time() then return cdnURL(cached.url) and cached.url or nil end
  for attempt=1,3 do
   local ok,response=pcall(transport,{Url="https://thumbnails.roblox.com/v1/assets?assetIds="..id.."&size=420x420&format=Png&isCircular=false",Method="GET"})
   if not ok or status(response)~=200 then break end
   local data=decode(response) local asset=data.data and data.data[1]
   if asset and asset.state=="Completed" and cdnURL(asset.imageUrl) then
    W.art[id]={url=asset.imageUrl,expires=os.time()+86400}
    pcall(function() writefile(W.artPath,Http:JSONEncode({version=1,items=W.art})) end)
    return asset.imageUrl
   end
   if not asset or asset.state~="Pending" or C.NoWorker then break end task.wait(.5)
  end
  W.art[id]={expires=os.time()+30} return nil
 end
 local snapshotFields={"UniqueItemID","name","rarity","imageId","levelReq","currentUpgrade","maxUpgrades","physicalDamage","physicalPower","spellPower","health","sellPrice","description"}
 function W.snapshot(record)
  if not record or type(record.item)~="table" then return nil end
  local copy={kind=record.kind,item={}}
  for _,key in ipairs(snapshotFields) do local value=record.item[key] if type(value)=="string" or type(value)=="number" then copy.item[key]=value end end
  return copy
 end
 function W.buildPayload(record,history,isTest,artURL)
  local item=record.item local fields={} local esc=string.char(27)
  local function line(label,value,code)
   local text=string.format("%-13s %s",label,clean(value,150))
   return W.config.ansi and esc.."[1;"..tostring(code or 37).."m"..text..esc.."[0m" or text
  end
  local function block(lines) return "```"..(W.config.ansi and "ansi" or "").."\n"..table.concat(lines,"\n").."\n```" end
  local function field(name,lines) if #lines>0 then table.insert(fields,{name=name,value=block(lines),inline=false}) end end
  local function integer(value) return A.integer(tonumber(value) or 0) end
  local class=A.Sorting.class(record) or "Other"
  local primary=class=="Guardian" and "health" or class=="Mage" and "spellPower" or record.kind=="weapon" and (item.physicalDamage~=nil and "physicalDamage" or "physicalPower") or "physicalPower"
  if record.kind=="ability" then primary=nil end
  local remaining=math.max(0,(tonumber(item.maxUpgrades) or 0)-(tonumber(item.currentUpgrade) or 0))
  local stats={}
  for _,spec in ipairs({{"physicalDamage","Physical",31},{"spellPower","Spell",35},{"health","Health",32}}) do
   local key,label,color=spec[1],spec[2],spec[3]
   local actual=key=="physicalDamage" and (item.physicalDamage or item.physicalPower) or item[key]
   if actual~=nil then
    table.insert(stats,line(label,integer(actual),color))
    if primary==key or primary=="physicalPower" and key=="physicalDamage" then table.insert(stats,line("Max "..label,integer(A.potential(actual,remaining)),color)) end
   end
  end
  field("Combat stats",stats)
  if record.kind=="ability" and item.description then field("Ability effect",{line("Effect",clean(item.description,450),36)}) end
  local percent,detail=A.compute(item,record.kind)
  local potential={}
  if percent then table.insert(potential,line("Godpot",A.text(percent),percent>=75 and 32 or percent>=35 and 33 or 31)) end
  if detail then
   table.insert(potential,line("Min roll",integer(detail.minimum),36)) table.insert(potential,line("Max roll",integer(detail.maximum),36))
   table.insert(potential,line("To perfect",integer(math.max(0,detail.maximum-detail.potential)),33))
  end
  local comparison=A.compare(record,A.equipped(record.kind))
  if comparison and comparison.delta then table.insert(potential,line("vs equipped",(comparison.delta>0 and "+" or comparison.delta<0 and "-" or "")..integer(math.abs(comparison.delta)),comparison.delta>0 and 32 or comparison.delta<0 and 31 or 36)) end
  field("Roll potential",potential)
  local details={}
  if item.levelReq~=nil then table.insert(details,line("Level",integer(item.levelReq),36)) end
  if item.maxUpgrades~=nil then table.insert(details,line("Upgrades",integer(item.currentUpgrade).." / "..integer(item.maxUpgrades),36)) end
  if item.sellPrice~=nil then table.insert(details,line("Sell value",integer(item.sellPrice),33)) end
  local cost=record.kind~="ability" and A.Extras.upgradeCost(item)
  if cost then table.insert(details,line("Gold to max",cost==0 and "Maxed" or integer(cost),cost==0 and 32 or 33)) end
  field("Item details",details)
  local palette={common=0x989898,uncommon=0x5BC250,rare=0x4B4DC3,epic=0x92469F,legendary=0xF49A09,ultimate=0xFF4040,mythic=0xEE5685,divine=0x67D8EE}
  local rarity=clean(item.rarity or "Unknown",30) local slot=record.kind=="chest" and "Armor" or record.kind=="helmet" and "Helmet" or record.kind=="weapon" and "Weapon" or "Ability"
  local embed={title=(isTest and "TEST · " or "")..clean(item.name or "Item drop",230),description="**"..rarity:upper().."** · "..clean(class,30).." · "..slot.."\n"..(isTest and "Webhook preview · not a new drop" or "Dropped in **"..clean(history.source or "Dungeon",160).."**"),color=palette[rarity:lower()] or 0xDAC36B,fields=fields,timestamp=DateTime.fromUnixTimestamp(tonumber(history.droppedAt) or os.time()):ToIsoDate(),footer={text=isTest and "Inv++ · Webhook test" or "Inv++ · Confirmed dungeon drop"}}
  if cdnURL(artURL) then embed.thumbnail={url=artURL} end
  return {username="Inv++",allowed_mentions={parse={}},embeds={embed}}
 end
 function W.classifyResponse(response)
  local code=status(response)
  if code and code>=200 and code<300 then
   local delay=tonumber(header(response,"X-RateLimit-Remaining"))==0 and tonumber(header(response,"X-RateLimit-Reset-After")) or 0
   return "sent",math.max(0,delay or 0),code
  end
  if code==429 then
   local data=decode(response) local seconds=tonumber(data.retry_after) or tonumber(header(response,"Retry-After")) or 2
   if seconds~=seconds or seconds==math.huge then seconds=2 end
   return "retry",math.max(.25,seconds)+.1,code
  end
  if not code or code>=500 then return "uncertain",0,code end
  return "failed",0,code
 end
 function W.enqueue(record,history,isTest)
  local url,destination=W.parseURL(W.config.url)
  if not W.config.enabled or not url then return false end
  if W.queueReadError or type(transport)~="function" then W.status="Delivery queue or HTTP requests are unavailable." W.lastError=W.status return false end
  local uid=isTest and "test_"..Http:GenerateGUID(false) or record and record.item.UniqueItemID
  if type(uid)~="string" or uid=="" then return false end
  if W.outbox.items[uid] or not isTest and history.webhookSentAt then return false end
  if W.pendingCount()>=64 then W.status="Webhook queue is full; check delivery status." W.lastError=W.status return false end
  local snapshot=W.snapshot(record) if not snapshot then return false end
  W.outbox.items[uid]={uid=uid,state="queued",queuedAt=os.time(),destination=destination,record=snapshot,history={droppedAt=history.droppedAt,source=history.source},isTest=isTest==true,attempts=0}
  W.status=isTest and "Test embed queued." or "Drop notification queued." W.lastError=nil
  return W.saveQueue()
 end
 function W.onDrop(uid,history,record)
  if not W.alive or not W.config.enabled or not history.droppedAt or history.acquisition~="drop" or history.confirmation~="reward-inventory-match" or history.droppedAt<(W.config.enabledAt or 0) then return false end
  if not record then for _,r in pairs(A.index) do if r.item.UniqueItemID==uid then record=r break end end end
  return W.enqueue(record,history,false)
 end
 function W.sendTest()
  if not W.config.enabled then W.status="Save and enable the webhook first." W.lastError=W.status return false end
  local best,bestPot
  for _,r in pairs(A.index) do local pot=A.compute(r.item,r.kind) if not best or pot and (not bestPot or pot>bestPot) then best=r bestPot=pot end end
  if not best then W.status="Open inventory once to load an item for the test." W.lastError=W.status return false end
  return W.enqueue(best,{droppedAt=os.time(),source="Webhook preview"},true)
 end
 function W.step()
  if not W.alive or W.busy or not W.config.enabled or os.clock()<W.nextAt then return false end
  local url,destination=W.parseURL(W.config.url) if not url then return false end
  local selected
  for _,job in pairs(W.outbox.items) do if job.state=="queued" and (not selected or (tonumber(job.queuedAt) or 0)<(tonumber(selected.queuedAt) or 0) or job.queuedAt==selected.queuedAt and job.uid<selected.uid) then selected=job end end
  if not selected then return false end
  local job=selected W.busy=true
  local ok,err=pcall(function()
   if job.destination~=destination then job.state="failed" job.reason="Destination changed" W.saveQueue() return end
   local artURL=W.resolveArt(job.record.item.imageId)
   local payload=W.buildPayload(job.record,job.history,job.isTest,artURL)
   if not W.alive or not W.config.enabled or W.config.url~=url or W.outbox.items[job.uid]~=job then return end
   job.state="sending" job.attempts+=1 if not W.saveQueue() then job.state="queued" return end
   local requestOK,response=pcall(transport,{Url=url..(url:find("?",1,true) and "&wait=true" or "?wait=true"),Method="POST",Headers={["Content-Type"]="application/json"},Body=Http:JSONEncode(payload)})
   if not W.alive then return end
   local outcome,delay,code=W.classifyResponse(requestOK and response or nil)
   W.nextAt=os.clock()+delay W.lastError=nil
   if outcome=="sent" then
    W.sent+=1 W.status=job.isTest and "Test embed sent." or "Sent: "..clean(job.record.item.name,48)
    if not job.isTest then
     local entry=A.History.store.items[job.uid]
     if entry then entry.webhookSentAt=os.time() A.History.changed() A.History.save() end
    end
    W.outbox.items[job.uid]=nil
   elseif outcome=="retry" then job.state="queued" W.status="Discord rate limit; queued notifications will resume."
   else
    job.state=outcome job.reason=code and "HTTP "..code or "Connection interrupted"
    W.status=outcome=="uncertain" and "Delivery unconfirmed; this item will not be repeated automatically." or "Discord rejected the notification (HTTP "..tostring(code)..")."
    W.lastError=W.status
    if code==400 or code==401 or code==403 or code==404 then W.config.enabled=false W.save() end
   end
   W.saveQueue()
  end)
  W.busy=false
  if not ok then job.state=job.state=="sending" and "uncertain" or "failed" job.reason="Could not prepare notification" W.status=job.reason W.lastError=W.status W.saveQueue() end
  return ok
 end
 function W.destroy() W.alive=false W.saveQueue() end
 if not C.NoWorker then task.spawn(function() while W.alive and C.App.Alive do W.step() task.wait(.25) end end) end
 return W
end
end

Modules.cards=function()
-- Opt-in native gear percentages and a matching hover-card stat row.
return function(C)
 local P=game:GetService("Players").LocalPlayer
 local A={alive=true,labels={},index={},connections={},tooltips={},SessionStartedAt=C.App.SessionStartedAt}
 local DATA,ALIASES=Modules.data()
 local rarityIndex={common=1,uncommon=2,rare=3,epic=4}
 local matchers,cache={},{}
 local function normalize(value)
  return tostring(value or ""):lower():gsub("’","'"):gsub("‘","'"):gsub("–","-"):gsub("—","-"):gsub("%s+"," "):match("^%s*(.-)%s*$")
 end
 local seen={}
 local function alias(name,target)
  name=normalize(name)
  if not seen[name] and DATA[target] and DATA[target].a then
   seen[name]=true table.insert(matchers,{name=name,entry=DATA[target]})
  end
 end
 for name,entry in pairs(DATA) do if entry.a then alias(name,name) end end
 for _,pair in ipairs(ALIASES or {}) do alias(pair[1],pair[2]) end
 alias("crystalline guardian","crystalline guadian")
 alias("rogue guardian","rouge guardian") alias("rogue","rouge")
 table.sort(matchers,function(a,b) if #a.name==#b.name then return a.name<b.name end return #a.name>#b.name end)
 function A.entry(name,kind)
  if kind=="ability" then return nil end
  local n=normalize(name)
  if DATA[n] then return DATA[n] end
  if kind~="helmet" and kind~="chest" then return nil end
  if cache[n]~=nil then return cache[n] or nil end
  for _,m in ipairs(matchers) do if n:find(m.name,1,true) then cache[n]=m.entry return m.entry end end
  cache[n]=false return nil
 end
 function A.potential(value,count)
  value=tonumber(value)
  if not value or value~=value or math.abs(value)==math.huge then return nil end
  count=math.max(0,math.floor(tonumber(count) or 0))
  while count>0 do
   local gain=math.clamp(math.floor(value*0.05),1,10)
   if gain==10 then return math.floor(value+count*10) end
   if value<0 then local n=math.min(count,math.ceil(-value)) value+=n count-=n else value+=gain count-=1 end
  end
  return math.floor(value)
 end
 function A.field(item,kind,entry)
  local class=normalize(entry.c)
  if class:find("guardian",1,true) then return "health" end
  if class:find("mage",1,true) then return "spellPower" end
  local physical=kind=="weapon" and (item.physicalDamage~=nil and "physicalDamage" or "physicalPower") or "physicalPower"
  if class:find("war",1,true) then return physical end
  return (tonumber(item[physical]) or 0)>=(tonumber(item.spellPower) or 0) and physical or "spellPower"
 end
 function A.compute(item,kind)
  if type(item)~="table" then return nil end
  local entry=A.entry(item.name,kind)
  if not entry then return nil end
  local field=A.field(item,kind,entry)
  if item[field]==nil then return nil end
  local current=math.max(0,math.floor(tonumber(item.currentUpgrade) or 0))
  local maximum=math.max(current,math.floor(tonumber(item.maxUpgrades) or current))
  local potential=A.potential(item[field],maximum-current)
  if not potential then return nil end
  local tier=entry.t[rarityIndex[normalize(item.rarity)] or 0]
  if not tier and #entry.t==1 then tier=entry.t[1] end
  if not tier then
   -- Ambiguous tiers stay unlabelled rather than borrowing a different rarity's range.
   local candidates={}
   for _,t in ipairs(entry.t) do
    if maximum>=t[1] and maximum<=t[2] and potential>=t[5] and potential<=t[6] then table.insert(candidates,t) end
   end
   if #candidates==1 then tier=candidates[1] end
  end
  if not tier then return nil end
  local low,high=tier[5],tier[6]
  if not low or not high or high<low then return nil end
  local raw=high>low and (potential-low)/(high-low)*100 or (potential>=high and 100 or 0)
  -- Round normally, but never show 100% for a nearly perfect roll.
  local percent=potential>=high and 100 or math.min(99.9,math.floor(math.clamp(raw,0,100)*10+0.5)/10)
  return percent,{potential=potential,minimum=low,maximum=high,field=field,dungeon=entry.d}
 end
 function A.ingest(inv)
  A.index={}
  for kind,container in pairs({weapon="weapons",helmet="helmets",chest="chests",ability="abilities"}) do
   for key,item in pairs(inv and inv[container] or {}) do
    if type(item)=="table" then
     local id=tostring(key):match("^[^_]+_(.+)$")
     if id then A.index[kind..":"..id]={item=item,kind=kind} end
    end
   end
  end
  if A.History then A.History.ingest(A.index) end
  if A.Review then A.Review.sync() end
  if A.Extras then A.Extras.rebuild() end
 end
 function A.color(percent)
  local red,yellow,green=Color3.fromRGB(242,105,105),Color3.fromRGB(245,216,103),Color3.fromRGB(135,232,121)
  return percent<=50 and red:Lerp(yellow,percent/50) or yellow:Lerp(green,(percent-50)/50)
 end
 function A.text(percent)
  return (string.format("%.1f",percent):gsub("%.0$","")).."%"
 end
 function A.compact(value)
  local n=math.abs(value)
  for _,unit in ipairs({{1e12,"T"},{1e9,"B"},{1e6,"M"},{1e3,"K"}}) do
   if n>=unit[1] then return (string.format("%.2f",value/unit[1]):gsub("0+$", ""):gsub("%.$", ""))..unit[2] end
  end
  return tostring(math.floor(value))
 end
 function A.equipped(kind)
  local inv=P.PlayerGui:FindFirstChild("inventory")
  local main=inv and inv:FindFirstChild("mainBackground")
  local inner=main and main:FindFirstChild("innerBackground")
  local left=inner and inner:FindFirstChild("leftSideFrame")
  local slot=left and left:FindFirstChild(kind.."Slot")
  local t=slot and slot:FindFirstChild("itemType") local id=t and t:FindFirstChild("uniqueItemNum")
  if id and A.index[kind..":"..tostring(id.Value)] then return A.index[kind..":"..tostring(id.Value)] end
  for _,r in pairs(A.index) do
   local equipped=r.item.equipped
   if type(equipped)=="table" then local found=false for _,v in pairs(equipped) do if v then found=true break end end equipped=found end
   if r.kind==kind and equipped==true then return r end
  end
 end
 function A.compare(record,equipped)
  if not record or record.kind=="ability" then return nil end
  local item=record.item local entry=A.entry(item.name,record.kind) or {c=""}
  local field=A.field(item,record.kind,entry)
  local function project(data)
   return A.potential(data[field],math.max(0,(tonumber(data.maxUpgrades) or 0)-(tonumber(data.currentUpgrade) or 0)))
  end
  local value=project(item) if not value then return nil end
  local result={value=value,field=field,label=field=="health" and "Max HP:" or field=="spellPower" and "Max Spell:" or "Max Phys:"}
  if equipped and equipped.kind==record.kind then
   result.equipped=project(equipped.item)
   if result.equipped then result.delta=value-result.equipped end
  end
  return result
 end
 function A.restoreTooltip(frame,state)
  for object,props in pairs(state.original) do
   if object.Parent then for key,value in pairs(props) do object[key]=value end end
  end
  state.title:Destroy() state.value:Destroy()
  for _,x in ipairs(state.extras or {}) do x:Destroy() end
  A.tooltips[frame]=nil
 end
 function A.integer(value)
  local number=tonumber(value)
  if not number then return tostring(value or "—") end
  if number~=number or math.abs(number)==math.huge then return "—" end
  local digits=string.format("%.0f",math.abs(number))
  local grouped=digits:reverse():gsub("(%d%d%d)","%1,"):reverse():gsub("^,","")
  return (number<0 and "-" or "")..grouped
 end
 function A.displayNumber(value,isStat)
  local number=tonumber(value) if not number then return tostring(value or "—") end
  local prefs=A.Extras and A.Extras.prefs or {}
  if isStat and prefs.abbreviateStats then return A.compact(number) end
  return prefs.formatStatNumbers~=false and A.integer(number) or string.format("%.0f",number)
 end
 function A.statText(value,count)
  local current=tonumber(value)
  local maximum=A.potential(current,count)
  if not current or not maximum then return nil end
  return A.displayNumber(current,true).."\n("..A.displayNumber(maximum,true)..")"
 end
 function A.showStatPotentials(frame,state,record)
  if not record or record.kind=="ability" then return end
  local item=record.item
  local remaining=math.max(0,(tonumber(item.maxUpgrades) or 0)-(tonumber(item.currentUpgrade) or 0))
  local stats={physicalDamage=item.physicalDamage or item.physicalPower,spellPower=item.spellPower,health=item.health}
  local strongest=A.field(item,record.kind,A.entry(item.name,record.kind) or {c=""})
  if record.kind=="weapon" then
   strongest=(tonumber(stats.spellPower) or 0)>(tonumber(stats.physicalDamage) or 0) and "spellPower" or "physicalDamage"
  elseif strongest=="physicalPower" then strongest="physicalDamage" end
  state.statLayout=state.statLayout or {} state.projections=state.projections or {} state.statCurrent=state.statCurrent or {}
  local function ownLabel(source,name)
   local text=source:Clone() text:ClearAllChildren() text.Name=name text.Visible=true
   text.SizeConstraint=Enum.SizeConstraint.RelativeXY text.AutomaticSize=Enum.AutomaticSize.None
   text.BackgroundTransparency=1 text.TextTransparency=0 text.TextStrokeTransparency=1
   text.TextScaled=false text.TextWrapped=false text.TextTruncate=Enum.TextTruncate.None
   text.Font=Enum.Font.Highway text.TextXAlignment=Enum.TextXAlignment.Right text.TextYAlignment=Enum.TextYAlignment.Center
   text.Parent=frame table.insert(state.extras,text) return text
  end
  local function fit(text,maximum)
   local width=math.max(1,text.AbsoluteSize.X-2) local height=math.max(1,text.AbsoluteSize.Y)
   local size=math.max(9,math.min(maximum,math.floor(height*.92)))
   local service=game:GetService("TextService")
   while size>9 and service:GetTextSize(text.Text,size,text.Font,Vector2.new(10000,10000)).X>width do size-=1 end
   text.TextSize=size
  end
  for name,value in pairs(stats) do
   local target=frame:FindFirstChild(name)
   if target and target:IsA("TextLabel") and tonumber(value) then
    local props=state.original[target]
    if props then
     if props.Visible==nil then props.Visible=target.Visible end
     props.Text=string.format("%.0f",tonumber(value))
    end
    local layout=state.statLayout[name]
    if not layout then layout={position=target.Position,size=target.Size} state.statLayout[name]=layout end
    target.Visible=false
    local current=state.statCurrent[name]
    if not current then current=ownLabel(target,"InvPlusStatCurrent_"..name) state.statCurrent[name]=current end
    current.Visible=true current.Text=A.displayNumber(value,true) current.TextColor3=target.TextColor3
    local show=name==strongest local projection=state.projections[name]
    if show and not projection then projection=ownLabel(target,"InvPlusStatMax_"..name) state.projections[name]=projection end
    local pos,size=layout.position,layout.size
    current.Position=pos current.Size=UDim2.new(size.X.Scale,size.X.Offset,size.Y.Scale*(show and .56 or 1),size.Y.Offset*(show and .56 or 1))
    fit(current,show and 22 or 28)
    if projection then
     projection.Visible=show
     if show then
      projection.Position=UDim2.new(pos.X.Scale,pos.X.Offset,pos.Y.Scale+size.Y.Scale*.56,pos.Y.Offset+size.Y.Offset*.56)
      projection.Size=UDim2.new(size.X.Scale,size.X.Offset,size.Y.Scale*.44,size.Y.Offset*.44)
      projection.Text="("..A.displayNumber(A.potential(value,remaining),true)..")" projection.TextColor3=target.TextColor3
      fit(projection,17)
     end
    end
    local title=frame:FindFirstChild(name=="physicalDamage" and "physicalDamageTitle" or name.."Title")
    if title then
     local original=state.original[title]
     if original and original.TextScaled==nil then original.TextScaled=title.TextScaled original.TextWrapped=title.TextWrapped end
     title.TextScaled=true title.TextWrapped=true
    end
   end
  end
 end
 function A.layoutFooter(frame,state,record)
  local item=record.item
  local definitions={
   {key="level",title="damageTitle",value="levelReq",text="REQ Lvl.",number=A.displayNumber(item.levelReq or frame.levelReq.Text)},
   {key="upgrades",title="upgradeTitle",value="upgrades",text="Upgrades:",number=A.displayNumber(item.currentUpgrade or 0).." / "..A.displayNumber(item.maxUpgrades or 0)},
   {key="sell",title="sellTitle",value="sellPrice",text="Sell:",number=item.sellPrice and A.displayNumber(item.sellPrice) or frame.sellPrice.Text}}
  state.footer=state.footer or {}
  for i,def in ipairs(definitions) do
   local titleSource,valueSource=frame[def.title],frame[def.value]
   local row=state.footer[def.key]
   if not row then
    row={} state.footer[def.key]=row
    for _,pair in ipairs({{titleSource,"title"},{valueSource,"value"}}) do
     local original=state.original[pair[1]] if original and original.Visible==nil then original.Visible=pair[1].Visible end
     local text=pair[1]:Clone() text:ClearAllChildren() text.Name="InvPlusFooter_"..def.key.."_"..pair[2]
     text.AnchorPoint=Vector2.zero text.SizeConstraint=Enum.SizeConstraint.RelativeXY text.AutomaticSize=Enum.AutomaticSize.None
     text.Visible=true text.BackgroundTransparency=1 text.TextScaled=false text.TextWrapped=false text.TextTruncate=Enum.TextTruncate.None
     text.Font=Enum.Font.Highway text.TextYAlignment=Enum.TextYAlignment.Center text.Parent=frame
     row[pair[2]]=text table.insert(state.extras,text)
    end
   end
   titleSource.Visible=false valueSource.Visible=false
   local y=(state.footerStart+(i-1)*.14)/state.factor
   row.title.Position=UDim2.fromScale(.04,y) row.title.Size=UDim2.fromScale(def.key=="upgrades" and .35 or .40,.125/state.factor)
   row.value.Position=UDim2.fromScale(def.key=="upgrades" and .40 or .49,y) row.value.Size=UDim2.fromScale(def.key=="upgrades" and .55 or .46,.125/state.factor)
   row.title.TextXAlignment=Enum.TextXAlignment.Left row.value.TextXAlignment=Enum.TextXAlignment.Right
   row.title.Text=def.text row.value.Text=def.number
   row.title.TextColor3=titleSource.TextColor3 row.value.TextColor3=valueSource.TextColor3
   if A.Extras then A.Extras.fitLabel(row.title,20) A.Extras.fitLabel(row.value,20) end
  end
 end
 function A.showTooltip(frame,percent,record)
  local state=A.tooltips[frame]
  if not state then
   state={original={},extras={}} A.tooltips[frame]=state
   local source=frame:FindFirstChild("healthTitle") or frame.spellPowerTitle
   local valueSource=frame:FindFirstChild("health") or frame.spellPower
   local rowY=source.Position.Y.Scale+source.Size.Y.Scale+.015
   local rowHeight=.14
   local cut=frame.damageTitle.Position.Y.Scale
   local detailStart=rowY+rowHeight+.045
   local footerStart=detailStart+3*.13+.11+.045
   local factor=footerStart+2*.14+.125+.035
   local shift=factor-1
   state.factor=factor state.footerStart=footerStart
   state.original[frame]={Size=frame.Size}
   for _,child in ipairs(frame:GetChildren()) do
    if child:IsA("GuiObject") and child.Name~="border" then
     state.original[child]={Position=child.Position,Size=child.Size}
     local pos,size=child.Position,child.Size
     child.Position=UDim2.new(pos.X.Scale,pos.X.Offset,(pos.Y.Scale+(pos.Y.Scale>=cut and shift or 0))/factor,pos.Y.Offset)
     child.Size=UDim2.new(size.X.Scale,size.X.Offset,size.Y.Scale/factor,size.Y.Offset)
    end
   end
   local size=frame.Size frame.Size=UDim2.new(size.X.Scale,size.X.Offset,size.Y.Scale*factor,size.Y.Offset*factor)
   state.title=source:Clone() state.title.Name="InvPlusGodpotTitle" state.title.Text="Godpot%:"
   state.title.Position=UDim2.new(source.Position.X.Scale,source.Position.X.Offset,rowY/factor,0)
   state.title.Size=UDim2.new(source.Size.X.Scale,source.Size.X.Offset,rowHeight/factor,0)
   state.title.Font=Enum.Font.Highway state.title.TextScaled=false state.title.TextWrapped=false state.title.Parent=frame
   state.value=valueSource:Clone() state.value.Name="InvPlusGodpotValue"
   state.value.Position=UDim2.new(valueSource.Position.X.Scale,valueSource.Position.X.Offset,rowY/factor,0)
   state.value.Size=UDim2.new(valueSource.Size.X.Scale,valueSource.Size.X.Offset,rowHeight/factor,0)
   state.value.Font=Enum.Font.Highway state.value.TextWrapped=true state.value.TextScaled=true
   state.value.TextXAlignment=Enum.TextXAlignment.Right state.value.Parent=frame
   for index,key in ipairs({"cost","delta","range","gap"}) do
    local y=(detailStart+(index-1)*.13)/factor
    local title=state.title:Clone() title.Name="InvPlusPotentialTitle_"..key title.Position=UDim2.new(source.Position.X.Scale,source.Position.X.Offset,y,0) title.Size=UDim2.new(source.Size.X.Scale,source.Size.X.Offset,.11/factor,0) title.Parent=frame
    local value=state.value:Clone() value.Name="InvPlusPotentialValue_"..key value.Position=UDim2.new(valueSource.Position.X.Scale,valueSource.Position.X.Offset,y,0) value.Size=UDim2.new(valueSource.Size.X.Scale,valueSource.Size.X.Offset,.11/factor,0) value.Parent=frame
    title.TextScaled=true title.TextWrapped=false
    local cap=Instance.new("UITextSizeConstraint") cap.MinTextSize=10 cap.MaxTextSize=18 cap.Parent=title
    local valueCap=cap:Clone() valueCap.Parent=value value.TextWrapped=false
    state[key.."Title"]=title state[key.."Value"]=value
    table.insert(state.extras,title) table.insert(state.extras,value)
   end
  end
  -- Reserve one value column for stats, quality, details and the footer.
  for _,name in ipairs({"physicalDamage","spellPower","health"}) do
   local value=frame:FindFirstChild(name)
   if value and not state.statLayout then value.Position=UDim2.new(.49,0,value.Position.Y.Scale,value.Position.Y.Offset) value.Size=UDim2.new(.46,0,value.Size.Y.Scale,value.Size.Y.Offset) end
  end
  for _,value in ipairs({state.value,state.costValue,state.deltaValue,state.rangeValue,state.gapValue}) do
   value.Position=UDim2.new(.49,0,value.Position.Y.Scale,value.Position.Y.Offset) value.Size=UDim2.new(.46,0,value.Size.Y.Scale,value.Size.Y.Offset)
  end
  A.layoutFooter(frame,state,record)
  A.showStatPotentials(frame,state,record)
  local textSize=math.max(10,math.floor(math.min(frame.levelReq.AbsoluteSize.Y*.85,state.title.AbsoluteSize.X/4.6)))
  state.title.TextSize=textSize
  state.title.TextColor3=A.color(percent) state.value.TextColor3=A.color(percent) state.value.Text=A.text(percent)
  local result=A.compare(record,record and A.equipped(record.kind))
  local neutral=Color3.fromRGB(230,230,230)
  local statColor=result and (result.field=="health" and Color3.fromRGB(153,231,135) or result.field=="spellPower" and Color3.fromRGB(191,155,235) or Color3.fromRGB(255,132,132)) or neutral
  state.deltaTitle.Text="vs worn:"
  local delta=result and result.delta
  state.deltaValue.Text=delta and (delta>0 and "+" or "")..A.compact(delta) or "—"
  state.deltaValue.TextColor3=delta and (delta>0 and Color3.fromRGB(135,232,121) or delta<0 and Color3.fromRGB(255,119,119) or Color3.fromRGB(129,203,255)) or neutral
  state.deltaTitle.TextColor3=state.deltaValue.TextColor3
  local cost=A.Extras and record and A.Extras.upgradeCost(record.item)
  local gold=A.Extras and A.Extras.gold()
  state.costTitle.Text="Gold to max:" state.costTitle.TextColor3=Color3.fromRGB(255,220,103)
  state.costValue.Text=cost and (cost==0 and "Maxed" or A.compact(cost)) or "—"
  state.costValue.TextColor3=cost and gold and (cost<=gold and Color3.fromRGB(135,232,121) or Color3.fromRGB(242,105,105)) or neutral
  local _,detail=A.compute(record.item,record.kind)
  state.rangeTitle.Text="Roll range:" state.rangeTitle.TextColor3=statColor
  state.rangeValue.Text=detail and A.compact(detail.minimum).."–"..A.compact(detail.maximum) or "—" state.rangeValue.TextColor3=statColor
  state.gapTitle.Text="To perfect:" state.gapTitle.TextColor3=Color3.fromRGB(255,189,102)
  local gap=detail and math.max(0,detail.maximum-detail.potential)
  state.gapValue.Text=gap and (gap==0 and "Perfect" or A.compact(gap)) or "—"
  state.gapValue.TextColor3=gap==0 and Color3.fromRGB(135,232,121) or A.color(percent)
  if A.Extras then
   for _,key in ipairs({"cost","delta","range","gap"}) do A.Extras.fitLabel(state[key.."Title"],18) A.Extras.fitLabel(state[key.."Value"],18) end
   A.Extras.fitLabel(state.title,22) A.Extras.fitLabel(state.value,28)
  end
  local inv=P.PlayerGui:FindFirstChild("inventory")
  if inv and frame.AbsoluteSize.Y<inv.AbsoluteSize.Y-16 then
   local y=frame.AbsolutePosition.Y local clamped=math.clamp(y,8,inv.AbsoluteSize.Y-frame.AbsoluteSize.Y-8)
   if clamped~=y then
    state.original[frame].Position=frame.Position
    frame.Position=frame.Position+UDim2.fromOffset(0,clamped-y)
   end
  end

 end
 function A.updateTooltip(enabled)
  local inv=P.PlayerGui:FindFirstChild("inventory")
  local root=inv and inv:FindFirstChild("itemStatFrame")
  local record=A.History.hovered()
  local function shown(object)
   while object and object~=P.PlayerGui do
    if object:IsA("GuiObject") and not object.Visible then return false end
    if object:IsA("ScreenGui") and not object.Enabled then return false end
    object=object.Parent
   end
   return true
  end
  local occluders={}
  local historyShown=false
  if root then
   for _,frame in ipairs(root:GetChildren()) do
    if frame:IsA("GuiObject") and shown(frame) then table.insert(occluders,frame) end
    local name=frame:FindFirstChild("name")
    local percent=enabled and record and name and normalize(name.Text)==normalize(record.item.name) and A.compute(record.item,record.kind)
    local eligible=frame.Name=="armorMain" or frame.Name=="weaponMain"
    local state=A.tooltips[frame]
    if percent and eligible and shown(frame) then
     A.showTooltip(frame,percent,record)
    elseif state then A.restoreTooltip(frame,state) end
    if C.on("ItemHistory") and record and name and normalize(name.Text)==normalize(record.item.name) and shown(frame) then
     local history=A.History.show(frame,record) if history then table.insert(occluders,history) historyShown=true end
    end
   end
  end
  if not historyShown then A.History.hide() end
  for card,label in pairs(A.labels) do
   local visible=true
   for _,frame in ipairs(occluders) do
    local a,b,c,d=label.AbsolutePosition,label.AbsoluteSize,frame.AbsolutePosition,frame.AbsoluteSize
    if a.X<c.X+d.X and a.X+b.X>c.X and a.Y<c.Y+d.Y and a.Y+b.Y>c.Y then visible=false break end
   end
   label.Visible=visible
  end
  if A.Extras then A.Extras.occlude(occluders) end
  A.animateGradients(enabled)
 end
 function A.rarityColor(rarity,percent)
  local palette={
   common={Color3.fromRGB(225,225,225),Color3.fromRGB(78,78,78)},
   uncommon={Color3.fromRGB(190,238,177),Color3.fromRGB(24,88,40)},
   rare={Color3.fromRGB(183,200,255),Color3.fromRGB(32,40,117)},
   epic={Color3.fromRGB(231,185,242),Color3.fromRGB(82,29,104)},
   legendary={Color3.fromRGB(255,226,156),Color3.fromRGB(151,83,6)},
   ultimate={Color3.fromRGB(255,185,181),Color3.fromRGB(124,20,29)},
   mythic={Color3.fromRGB(255,185,181),Color3.fromRGB(124,20,29)},
   divine={Color3.fromRGB(193,244,255),Color3.fromRGB(24,94,115)}}
  local key=tostring(rarity or ""):lower() if key=="mythical" then key="mythic" end
  local colors=palette[key] if not colors or tonumber(percent)==nil then return nil end
  return colors[1]:Lerp(colors[2],math.clamp(percent/100,0,1))
 end
 function A.shadePercent(percent,detail)
  if detail and detail.maximum>detail.minimum then return math.clamp((detail.potential-detail.minimum)/(detail.maximum-detail.minimum)*100,0,100) end
  return percent
 end
 function A.animateGradients(enabled,now)
  local prefs=A.Extras and A.Extras.prefs or {}
  if not enabled or not prefs.animatedGradients or prefs.rarityGradients==false then
   if A.gradientsMoving then
    for _,state in pairs(A.rarityTints or {}) do if state.gradient and state.gradient.Parent then state.gradient.Rotation=45 state.gradient.Offset=Vector2.zero end end
   end
   A.gradientsMoving=false A.gradientVisible=nil A.gradientVisibilityAt=nil return
  end
  local inv=P.PlayerGui:FindFirstChild("inventory") local main=inv and inv:FindFirstChild("mainBackground")
  if not main or not main.Visible or not inv.Enabled then return end
  local stamp=now or os.clock() A.gradientsMoving=true
  local phase=stamp%4/4
  local rotation=45+phase*360
  local offset=Vector2.new(math.sin(phase*math.pi*2)*.26,math.cos(phase*math.pi*2)*.16)
  -- Only visibility checks are throttled. Gradient motion updates on every
  -- RenderStepped frame, including 240 Hz, without rebuilding color sequences.
  if now or not A.gradientVisible or not A.gradientVisibilityAt or stamp-A.gradientVisibilityAt>=1/30 then
   A.gradientVisibilityAt=stamp A.gradientVisible={}
   for card,state in pairs(A.rarityTints or {}) do
    local gradient=state.gradient
    if gradient and gradient.Enabled and card.Parent and card.Visible then
     local visible=true local p,size=card.AbsolutePosition,card.AbsoluteSize local ancestor=card.Parent
     while ancestor and ancestor~=P.PlayerGui do
      if ancestor:IsA("GuiObject") then
       if not ancestor.Visible then visible=false break end
       if ancestor.ClipsDescendants then
        local q,bounds=ancestor.AbsolutePosition,ancestor.AbsoluteSize
        if p.X>=q.X+bounds.X or p.X+size.X<=q.X or p.Y>=q.Y+bounds.Y or p.Y+size.Y<=q.Y then visible=false break end
       end
      end
      ancestor=ancestor.Parent
     end
     if visible then A.gradientVisible[#A.gradientVisible+1]={card=card,gradient=gradient} end
    end
   end
  end
  for _,entry in ipairs(A.gradientVisible) do
   if entry.card.Parent and entry.card.Visible and entry.gradient.Parent and entry.gradient.Enabled then entry.gradient.Rotation=rotation entry.gradient.Offset=offset end
  end
 end
 function A.restoreRarity(card)
  local state=A.rarityTints and A.rarityTints[card]
  if state then
   if state.gradient then state.gradient:Destroy() end
   if card.Parent then card.ImageColor3=state.color end
   A.rarityTints[card]=nil
  end
 end
 function A.shadeCard(card,record,percent,detail,scope)
  A.rarityTints=A.rarityTints or {}
  local prefs=A.Extras and A.Extras.prefs or {}
  local shade=prefs.rarityShading~=false and percent~=nil and A.rarityColor(record.item.rarity,A.shadePercent(percent,detail))
  local useGradient=prefs.rarityGradients~=false
  if not shade and not useGradient then A.restoreRarity(card) return false end
  local state=A.rarityTints[card]
  if state and state.rarity~=record.item.rarity then
   if state.gradient then state.gradient:Destroy() end
   A.rarityTints[card]=nil state=nil
  end
  if not state then state={color=card.ImageColor3,rarity=record.item.rarity,scope=scope or "inventory"} A.rarityTints[card]=state end
  local base=shade or state.color
  if useGradient then
   if not state.gradient or state.gradient.Parent~=card or state.gradientBase~=base or state.gradientAnimated~=(prefs.animatedGradients==true) then
    local gradient=state.gradient
    if not gradient or gradient.Parent~=card then gradient=Instance.new("UIGradient") gradient.Name="InvPlusRarityGradient" gradient.Rotation=45 gradient.Parent=card state.gradient=gradient end
    local highlight=base:Lerp(Color3.new(1,1,1),prefs.animatedGradients and .26 or .12)
    local shadow=base:Lerp(Color3.new(0,0,0),prefs.animatedGradients and .40 or .26)
    local function relative(color) return Color3.new(color.R/math.max(highlight.R,1e-6),color.G/math.max(highlight.G,1e-6),color.B/math.max(highlight.B,1e-6)) end
    -- ImageColor3 supplies the narrow highlight; the three stops multiply it
    -- back to the exact Godpot color, then its same-hue shadow.
    gradient.Color=ColorSequence.new({ColorSequenceKeypoint.new(0,Color3.new(1,1,1)),ColorSequenceKeypoint.new(.32,relative(base)),ColorSequenceKeypoint.new(1,relative(shadow))})
    state.gradientBase=base state.displayColor=highlight state.gradientAnimated=prefs.animatedGradients==true
   end
   state.gradient.Enabled=true card.ImageColor3=state.displayColor
  else
   if state.gradient then state.gradient.Enabled=false end
   card.ImageColor3=base
  end
  return true
 end
 function A.clear()
  for card in pairs(A.rarityTints or {}) do A.restoreRarity(card) end
  for _,label in pairs(A.labels) do label:Destroy() end
  table.clear(A.labels)
  for frame,state in pairs(A.tooltips) do A.restoreTooltip(frame,state) end
 end
 function A.render(enabled)
  if not enabled then A.clear() return end
  local inv=P.PlayerGui:FindFirstChild("inventory")
  local main=inv and inv:FindFirstChild("mainBackground")
  local inner=main and main:FindFirstChild("innerBackground")
  if not inner then A.clear() return end
  local active={} local tinted={}
  local right=inner:FindFirstChild("rightSideFrame")
  local bag=right and right:FindFirstChild("ScrollingFrame")
  local left=inner:FindFirstChild("leftSideFrame")
  for _,container in ipairs({bag or false,left or false}) do
   if container then
    for _,card in ipairs(container:GetChildren()) do
     if card:IsA("GuiObject") then
      local t=card:FindFirstChild("itemType")
      local id=t and t:FindFirstChild("uniqueItemNum")
      local record=t and id and A.index[t.Value..":"..tostring(id.Value)]
      local percent,detail if record then percent,detail=A.compute(record.item,record.kind) end
      if record and A.shadeCard(card,record,percent,detail) then tinted[card]=true end
      if percent then
       local label=A.labels[card]
       if not label or label.Parent~=card then
        label=Instance.new("TextLabel") label.Name="InvPlusGodpotPercent"
        label.BackgroundColor3=Color3.fromRGB(20,20,20) label.BackgroundTransparency=0.18 label.BorderSizePixel=0 label.Active=false
        label.AnchorPoint=Vector2.new(1,1) label.Position=UDim2.fromScale(0.96,0.96) label.Size=UDim2.new(0.58,0,0.21,0)
        label.Font=Enum.Font.Highway label.TextScaled=true label.TextStrokeTransparency=1
        label.TextXAlignment=Enum.TextXAlignment.Center label.ZIndex=10
        local corner=Instance.new("UICorner") corner.CornerRadius=UDim.new(0,3) corner.Parent=label
        local padding=Instance.new("UIPadding") padding.PaddingLeft=UDim.new(0,3) padding.PaddingRight=UDim.new(0,3) padding.Parent=label
        local limit=Instance.new("UITextSizeConstraint") limit.MinTextSize=8 limit.MaxTextSize=11 limit.Parent=label
        label.Parent=card A.labels[card]=label
       end
       label.Text=A.text(percent)
       label.TextColor3=A.color(percent)
       active[card]=true
      end
     end
    end
   end
  end
  for card,label in pairs(A.labels) do if not active[card] then label:Destroy() A.labels[card]=nil end end
  for card,state in pairs(A.rarityTints or {}) do if not card.Parent or state.scope~="review" and not tinted[card] then A.restoreRarity(card) end end
 end
 function A.destroy()
  if A.Fleet then A.Fleet.destroy() end
  if A.AutoEquip then A.AutoEquip.destroy() end
  A.alive=false
  if A.Webhook then A.Webhook.destroy() end
  if A.Extras then A.Extras.destroy() end
  if A.History then A.History.destroy() end
  if A.Review then A.Review.destroy() end
  if A.Sorting then A.Sorting.destroy() end
  A.clear()
  for _,c in ipairs(A.connections) do c:Disconnect() end
  if C.Inventory.onUpdate==A.ingest then C.Inventory.onUpdate=nil end
 end
 A.History=Modules.history()({Godpot=A,Inventory=C.Inventory})
 A.Sorting=Modules.sorting()({Godpot=A})
 A.Review=Modules.review()({Godpot=A,Inventory=C.Inventory})
 A.Extras=Modules.extras()({Godpot=A,App=C.App})
 A.AutoEquip=Modules.autoequip()({Godpot=A,Inventory=C.Inventory})
 A.Fleet=Modules.fleet()({Godpot=A,Inventory=C.Inventory,App=C.App})
 A.Webhook=Modules.webhook()({Godpot=A,App=C.App})
 table.insert(A.connections,game:GetService("RunService").RenderStepped:Connect(function()
  if A.alive then local ok,err=pcall(A.updateTooltip,C.on("GodpotCards")) if not ok then A.lastError=tostring(err) end end
 end))
 C.Inventory.onUpdate=A.ingest
 if C.Inventory.cache then A.ingest(C.Inventory.cache) end
 local remotes=game:GetService("ReplicatedStorage"):FindFirstChild("remotes")
 if remotes then
  for _,name in ipairs({"reloadInventory","updateLocalInventoryTable"}) do
   local remote=remotes:FindFirstChild(name)
   if remote and remote:IsA("RemoteEvent") then
    table.insert(A.connections,remote.OnClientEvent:Connect(function()
     if C.on("GodpotCards") or C.on("ItemHistory") or A.Webhook and A.Webhook.config.enabled or A.AutoEquip and A.AutoEquip.enabled() then task.delay(0.3,function() if A.alive then C.Inventory.fetch() end end) end
    end))
   end
  end
 end
 task.spawn(function()
  local lastFetch=-math.huge
  while A.alive and C.App.Alive do
   local ok,err=pcall(function()
    local enabled=C.on("GodpotCards")
    if (enabled or C.on("ItemHistory") or A.Webhook and A.Webhook.config.enabled or A.AutoEquip and A.AutoEquip.enabled() or A.Sorting.mode or A.Sorting.query~="") and os.clock()-lastFetch>=8 then lastFetch=os.clock() C.Inventory.fetch() end
    A.Review.update()
    A.Sorting.update()
    A.Extras.update()
    A.render(enabled)
   end)
   if not ok then A.lastError=tostring(err) warn("[InvPlus Godpot%] "..tostring(err)) end
   task.wait(0.3)
  end
 end)
 return A
end


end

-- Standalone runtime. Everything above is bundled inventory code and item data.
if not game:IsLoaded() then game.Loaded:Wait() end
local env=getgenv()
if env.InvPlus and env.InvPlus.Unload then env.InvPlus.Unload() end
-- Replace the full edition when explicitly executing the inventory-only edition.
if env.Laplace and env.Laplace.Unload then env.Laplace.Unload() end
local Players=game:GetService("Players")
local P=Players.LocalPlayer
while not P do Players:GetPropertyChangedSignal("LocalPlayer"):Wait() P=Players.LocalPlayer end
if not isfolder("Inv++") then makefolder("Inv++") end
local App={Name="Inv++",Version="1.6.1",Alive=true,Connections={}}
env.InvPlus=App
local session=env.InvPlusSession
if type(session)~="table" or session.userId~=P.UserId or type(session.startedAt)~="number" then session={userId=P.UserId,startedAt=os.time()} env.InvPlusSession=session end
App.SessionStartedAt=session.startedAt
local defaults={GodpotCards=true,ItemHistory=true,RerunOnTeleport=false}
local settings=type(env.InvPlusSettings)=="table" and env.InvPlusSettings or {}
for key,value in pairs(defaults) do if settings[key]==nil then settings[key]=value end end
env.InvPlusSettings=settings App.Settings=settings
local Inventory={cache=nil,lastFetch=-math.huge,busy=false}
function Inventory.fetch(force)
 if not App.Alive or Inventory.busy or not force and os.clock()-Inventory.lastFetch<2 then return Inventory.cache end
 local remotes=game:GetService("ReplicatedStorage"):FindFirstChild("remotes")
 local remote=remotes and remotes:FindFirstChild("reloadInvy")
 if not remote or not remote:IsA("RemoteFunction") then return Inventory.cache end
 Inventory.lastFetch=os.clock() Inventory.busy=true
 local ok,inv=pcall(function() return remote:InvokeServer() end)
 Inventory.busy=false
 if ok and type(inv)=="table" and App.Alive then
  Inventory.cache=inv
  Inventory.lastSuccess=os.time()
  if Inventory.onUpdate then Inventory.onUpdate(inv) end
 elseif not ok then App.LastFetchError=tostring(inv) end
 return Inventory.cache
end
App.InventorySource=Inventory
function App.Unload()
 if not App.Alive then return end App.Alive=false
 if App.Inventory then App.Inventory.destroy() end
 for _,connection in ipairs(App.Connections) do connection:Disconnect() end
 if env.InvPlus==App then env.InvPlus=nil end
end
local ok,feature=xpcall(function()
 return Modules.cards()({Inventory=Inventory,App=App,on=function(key) return settings[key]==true end})
end,debug.traceback)
if not ok then App.Unload() error("[Inv++] "..tostring(feature)) end
App.Inventory=feature
Inventory.fetch()
feature.Sorting.update()
feature.Extras.update()
feature.render(settings.GodpotCards)
table.insert(App.Connections,P.OnTeleport:Connect(function(state)
 if state~=Enum.TeleportState.Started or not App.Alive or not settings.RerunOnTeleport then return end
 local queue=queue_on_teleport or (syn and syn.queue_on_teleport)
 if type(queue)=="function" then
  pcall(queue,string.format([[getgenv().InvPlusSession={userId=%d,startedAt=%d} repeat task.wait() until game:IsLoaded() task.wait(2) if isfile("Inv++.lua") then loadstring(readfile("Inv++.lua"))() end]],P.UserId,App.SessionStartedAt))
 end
end))
return App
]=], "Harvard bundled Inv++"))()
end


